const c="006",n=6,t="https://zh.wikisource.org/zh-hant/史記三家註/卷006",e="https://zh.wikisource.org/zh-hant/史記/卷006",o=JSON.parse('[{"id":"a1","section":"秦始皇本紀第六","anchor":"秦始皇帝者，秦莊襄王子也。","notes":[{"source":"索隱","text":"莊襄王者，孝文王之中子，昭襄王之孫也，名子楚。按：《戰國策》本名子異，後爲華陽夫人嗣，夫人楚人，因改名子楚也。"}]},{"id":"a2","section":"秦始皇本紀第六","anchor":"秦始皇帝者，秦莊襄王子也。莊襄王爲秦質子於趙，","notes":[{"source":"正義","text":"質音致。國彊欲待弱之來相事，故遣子及貴臣爲質，如上音。國弱懼其侵伐，令子及貴臣往爲質，音直實反。又二國敵亦爲交質，音致。《左傳》云周鄭交質，王子狐爲質於鄭，鄭公子忽爲質於周是也。"}]},{"id":"a3","section":"秦始皇本紀第六","anchor":"秦始皇帝者，秦莊襄王子也。莊襄王爲秦質子於趙，見呂不韋姬，悅而取之，","notes":[{"source":"索隱","text":"按：不韋傳云不韋，陽翟大賈也。其姬邯鄲豪家女，善歌舞，有娠而獻於子楚。"}]},{"id":"a4","section":"秦始皇本紀第六","anchor":"而取之，生始皇。以秦昭王四十八年正月生於邯鄲。及生，名爲政，姓趙氏。","notes":[{"source":"集解","text":"徐廣曰：「一作『正』。」宋忠云：「以正月旦生，故名正。」"},{"source":"索隱","text":"《系本》作「政」，又生於趙，故曰趙政。一曰秦與趙同祖，以趙城爲榮，故姓趙氏。"},{"source":"正義","text":"正音政，「周正建子」之「正」也。始皇以正月旦生於趙，因爲政，後以始皇諱，故音征。"}]},{"id":"a5","section":"秦始皇本紀第六","anchor":"韋爲相，封十萬戶，號曰文信侯。招致賓客游士，欲以并天下。李斯爲舍人。","notes":[{"source":"集解","text":"文穎曰：「主廄內小吏官名。或曰待從賓客謂之舍人也。」"}]},{"id":"a6","section":"秦始皇本紀第六","anchor":"萬戶，號曰文信侯。招致賓客游士，欲以并天下。李斯爲舍人。蒙驁、王齮、","notes":[{"source":"集解","text":"徐廣曰：「一作『齕』。」"},{"source":"索隱","text":"蒙驁，齊人，蒙武之父，蒙恬之祖。王齮即王齕，昭王四十九年代大夫陵伐趙者。"},{"source":"正義","text":"齮，魚綺反。劉伯莊云音綺。後同。"}]},{"id":"a7","section":"秦始皇本紀第六","anchor":"侯。招致賓客游士，欲以并天下。李斯爲舍人。蒙驁、王齮、麃公等爲將軍。","notes":[{"source":"集解","text":"應劭曰：「麃，秦邑。」"},{"source":"索隱","text":"麃公蓋麃邑公，史失其姓名。"},{"source":"正義","text":"麃，彼苗反，蓋秦之縣邑。大夫稱公，若楚制。"}]},{"id":"a8","section":"始皇二年","anchor":"二年，麃公將卒攻卷，","notes":[{"source":"正義","text":"將，子匠反。卒，子必反。卷，丘員反。"}]},{"id":"a9","section":"始皇三年","anchor":"三年，蒙驁攻韓，取十三城。王齮死。十月，將軍蒙驁攻魏氏畼、有詭。","notes":[{"source":"集解","text":"徐廣曰：「畼音場。」"},{"source":"索隱","text":"音暢，魏之邑名。"}]},{"id":"a10","section":"始皇五年","anchor":"五年，將軍驁攻魏，定酸棗、","notes":[{"source":"集解","text":"《地理志》陳留有酸棗縣。"},{"source":"正義","text":"《括地志》云：「酸棗故城在滑州酸棗縣北十五里古酸棗縣南。」"}]},{"id":"a11","section":"始皇五年","anchor":"五年，將軍驁攻魏，定酸棗、燕、虛、長平、","notes":[{"source":"集解","text":"徐廣曰：「一作『千』。」駰案：《地理志》汝南有長平縣也。"},{"source":"索隱","text":"二邑名。春秋桓十二年「會于虛」，又《戰國策》曰「拔燕酸棗、虛、桃人」，桃人亦魏邑，虛地今闕，蓋與諸縣相近。按：今東郡燕縣東三十里有故桃城，則亦非遠。"},{"source":"正義","text":"燕，烏田反。《括地志》云：「南燕城，古燕國也，滑州胙城縣是也。姚虛在濮州雷澤縣東十三里。孝經援神契云帝舜生於姚墟，即東郡也。長平故城在陳州宛丘縣西六十六里。」"}]},{"id":"a12","section":"始皇五年","anchor":"五年，將軍驁攻魏，定酸棗、燕、虛、長平、雍丘、山陽城，","notes":[{"source":"集解","text":"《地理志》陳留有雍丘縣，河內有山陽縣。"},{"source":"正義","text":"雍，於用反，汴州縣。"}]},{"id":"a13","section":"始皇六年","anchor":"六年，韓、魏、趙、衞、楚共擊秦，取壽陵。","notes":[{"source":"正義","text":"徐廣云：「在常山。」按：本趙邑也。"}]},{"id":"a14","section":"始皇七年","anchor":"七年，彗星先出東方，見北方，五月見西方。","notes":[{"source":"正義","text":"彗音似歲反。見，並音行練反。孝經內記云：「彗在北斗，兵大起。彗在三台，臣害君。彗在太微，君害臣。彗在天獄，諸侯作亂。所指其處大惡。彗在日旁，子欲殺父。」"}]},{"id":"a15","section":"始皇七年","anchor":"七年，彗星先出東方，見北方，五月見西方。將軍驁死。以攻龍、孤、慶都，","notes":[{"source":"集解","text":"徐廣曰：「慶，一作『麃』。」"},{"source":"正義","text":"《括地志》云：「定州恆陽縣西南四十里有白龍水，又有挾龍山。又定州唐縣東北五十四里有孤山。蓋都山也。《帝王紀》云望堯母慶都所居。張晏云堯山在北，堯母慶都山在南，相去五十里，北登堯山，南望慶都山也。《注水經》云『望都故城東有山，不連陵，名之曰孤』。孤都聲相近，疑即都山，孤山及望都故城三處相近。」"}]},{"id":"a16","section":"始皇七年","anchor":"北方，五月見西方。將軍驁死。以攻龍、孤、慶都，還兵攻汲。彗星復見西方","notes":[{"source":"正義","text":"復，扶富反。見，行見反。"}]},{"id":"a17","section":"始皇七年","anchor":"將軍驁死。以攻龍、孤、慶都，還兵攻汲。彗星復見西方十六日。夏太后死。","notes":[{"source":"索隱","text":"莊襄王所生母。"},{"source":"正義","text":"子楚母也。"}]},{"id":"a18","section":"始皇八年","anchor":"八年，王弟長安君成蟜","notes":[{"source":"正義","text":"蟜音紀兆反。成蟜者，長安君名也，號爲長安君。"}]},{"id":"a19","section":"始皇八年","anchor":"八年，王弟長安君成蟜將軍擊趙，反，","notes":[{"source":"正義","text":"將，如字。將猶領也。又子匠反。"}]},{"id":"a20","section":"始皇八年","anchor":"八年，王弟長安君成蟜將軍擊趙，反，死屯留，","notes":[{"source":"正義","text":"《括地志》云：「屯留故城在潞州長子縣東北三十里，漢屯留，留吁國也。」"}]},{"id":"a21","section":"始皇八年","anchor":"八年，王弟長安君成蟜將軍擊趙，反，死屯留，軍吏皆斬死，遷其民於臨洮。","notes":[{"source":"索隱","text":"臨洮在隴西。"},{"source":"正義","text":"臨洮水，故名臨洮。洮州在隴右，去京千五百五十一里。言屯留之民被成蟜略眾共反，故遷之於臨洮郡也。"}]},{"id":"a22","section":"始皇八年","anchor":"長安君成蟜將軍擊趙，反，死屯留，軍吏皆斬死，遷其民於臨洮。將軍壁死，","notes":[{"source":"正義","text":"壁，邊覓反。言成蟜自殺壁壘之內。"}]},{"id":"a23","section":"始皇八年","anchor":"死屯留，軍吏皆斬死，遷其民於臨洮。將軍壁死，卒屯留、蒲鶮反，戮其屍。","notes":[{"source":"集解","text":"徐廣曰：「鶮，一作『鶡』。屯留，蒲鶡，皆地名也。壁于此地時，士卒死者皆戮其屍。」"},{"source":"索隱","text":"高誘云屯留，上黨之縣名。謂成蟜爲將軍而反。秦兵擊之，而蟜壁於屯留而死。屯留、蒲鶮二邑之反卒雖死，猶皆戮其屍。鶮，古「鸖」字。"},{"source":"正義","text":"卒，子忽反。鶮音高，注同。蒲，鶮，皆地名。"}]},{"id":"a24","section":"始皇八年","anchor":"吏皆斬死，遷其民於臨洮。將軍壁死，卒屯留、蒲鶮反，戮其屍。河魚大上，","notes":[{"source":"索隱","text":"謂河水溢，魚大上平地，亦言遭水害也。即《漢書》五行志劉向所謂「豕蟲之孼」。明年，嫪毐誅。魚，陰類，小人象。"},{"source":"正義","text":"始皇八年，黃河之魚西上入渭。渭，渭水也。《漢書》五行志云「魚者陰類，臣民之象也」。十七年，滅韓。二十六年，盡并天下。自滅韓至并天下，蓋十年矣。周本紀云「十年，數之紀也。天之所棄，不過其紀」。明關東後屬秦，其象類先見也。"}]},{"id":"a25","section":"始皇八年","anchor":"死，遷其民於臨洮。將軍壁死，卒屯留、蒲鶮反，戮其屍。河魚大上，輕車重","notes":[{"source":"集解","text":"徐廣曰：「一無此『重』字。」"}]},{"id":"a26","section":"始皇八年","anchor":"於臨洮。將軍壁死，卒屯留、蒲鶮反，戮其屍。河魚大上，輕車重馬東就食。","notes":[{"source":"索隱","text":"言河魚大上，秦人皆輕車重馬，並就食於東。言往河旁食魚也。一云，河魚大上爲災，人遂東就食，皆輕車重馬而去。"}]},{"id":"a27","section":"始皇八年","anchor":"嫪毐","notes":[{"source":"索隱","text":"嫪，姓；毐，字。按：《漢書》嫪氏出邯鄲。王劭云「賈侍中說秦始皇母予嫪毐淫坐誅，故世人罵淫曰『嫪毐』也」。"},{"source":"正義","text":"上躬虬反，下酷改反。"}]},{"id":"a28","section":"始皇八年","anchor":"嫪毐封爲長信侯。予之山陽地，","notes":[{"source":"正義","text":"予音與。《括地志》云：「山陽故城在懷州修武縣西北太行山東南。」"}]},{"id":"a29","section":"始皇八年","anchor":"陽地，令毐居之。宮室車馬衣服苑囿馳獵恣毐。事無小大皆決於毐。又以河西","notes":[{"source":"集解","text":"徐廣曰：「河，一作『汾』。」"}]},{"id":"a30","section":"始皇九年","anchor":"九年，彗星見，或竟天。攻魏垣、蒲陽。四月，上宿雍。","notes":[{"source":"集解","text":"蔡邕曰：「上者，尊位所在也。」駰案：司馬遷記事，當言「帝」則依違但言「上」，不敢媟言，尊尊之意也。"}]},{"id":"a31","section":"始皇九年","anchor":"九年，彗星見，或竟天。攻魏垣、蒲陽。四月，上宿雍。己酉，王冠，帶劍。","notes":[{"source":"集解","text":"徐廣曰：「年二十二。」"},{"source":"正義","text":"冠音灌。《禮記》云年二十而冠。按：年二十一也。"}]},{"id":"a32","section":"始皇九年","anchor":"垣、蒲陽。四月，上宿雍。己酉，王冠，帶劍。長信侯毐作亂而覺，矯王御璽","notes":[{"source":"集解","text":"蔡邕曰：「御者，進也。凡衣服加於身，飲食入於口，妃妾接於寢，皆曰御。御之親愛者曰幸。璽者，印信也。天子璽白玉螭虎鈕。古者尊卑共之。月令曰『固封璽』，《左傳》曰『季武子璽書追而與之』，此諸侯大夫印稱璽也。」衞宏曰：「秦以前，民皆以金玉爲印，龍虎鈕，唯其所好。秦以來，天子獨以印稱璽，又獨以玉，羣臣莫敢用。」"},{"source":"正義","text":"崔浩云：「李斯磨和璧作之，漢諸帝世傳服之，謂『傳國璽』。」韋曜《吳書》云璽方四寸，上句交五龍，文曰「受命于天既壽永昌」。《漢書》云文曰「昊天之命皇帝壽昌」。按：二文不同。《漢書》元后傳云王莽令王舜逼太后取璽，王太后怒，投地，其角小缺。吳志云孫堅入洛，埽除漢陵廟，軍於甄官井得璽，後歸魏。晉懷帝永嘉五年六月，帝蒙塵平陽，璽入前趙劉聰。至東晉成帝咸和四年，石勒滅前趙，得璽。穆帝永和八年，石勒爲慕容俊滅，濮陽太守戴施入鄴，得璽，使何融送晉。傳宋，宋傳南齊，南齊傳梁。梁傳至天正二年，侯景破梁，至廣陵，北齊將辛術定廣陵，得璽，送北齊。至周建德六年正月，平北齊，璽入周。周傳隋，隋傳唐也。"}]},{"id":"a33","section":"始皇九年","anchor":"上宿雍。己酉，王冠，帶劍。長信侯毐作亂而覺，矯王御璽及太后璽以發縣卒","notes":[{"source":"正義","text":"子忽反，下同。"}]},{"id":"a34","section":"始皇九年","anchor":"御璽及太后璽以發縣卒及衞卒、官騎、戎翟君公、舍人，將欲攻蘄年宮爲亂。","notes":[{"source":"集解","text":"《地理志》蘄年宮在雍。"},{"source":"正義","text":"蘄，巨衣反。《括地志》云：「蘄年宮在岐州城西故城內。」"}]},{"id":"a35","section":"始皇九年","anchor":"君公、舍人，將欲攻蘄年宮爲亂。王知之，令相國昌平君、昌文君發卒攻毐。","notes":[{"source":"索隱","text":"昌平君，楚之公子，立以爲相，後徙於郢，項燕立爲荊王，史失其名。昌文君名亦不知也。"}]},{"id":"a36","section":"始皇九年","anchor":"人，將欲攻蘄年宮爲亂。王知之，令相國昌平君、昌文君發卒攻毐。戰咸陽，","notes":[{"source":"正義","text":"《括地志》云：「咸陽故城亦名渭城，在雍州北五里，今咸陽縣東十五里。秦孝公已下並都此城。始皇鑄金人十二於咸陽，即此也。」"}]},{"id":"a37","section":"始皇九年","anchor":"敗走。即令國中：有生得毐，賜錢百萬；殺之，五十萬。盡得毐等。衞尉竭、","notes":[{"source":"集解","text":"《漢書百官表》曰：「衞尉，秦官。」"}]},{"id":"a38","section":"始皇九年","anchor":"有生得毐，賜錢百萬；殺之，五十萬。盡得毐等。衞尉竭、內史肆、佐弋竭、","notes":[{"source":"集解","text":"《漢書百官表》曰：「秦時少府有佐弋，漢武帝改爲佽飛，掌弋射者。」"},{"source":"正義","text":"弋音翊。"}]},{"id":"a39","section":"始皇九年","anchor":"錢百萬；殺之，五十萬。盡得毐等。衞尉竭、內史肆、佐弋竭、中大夫令齊等","notes":[{"source":"正義","text":"令，力政反。中大夫令，秦官也。齊，名也。"}]},{"id":"a40","section":"始皇九年","anchor":"五十萬。盡得毐等。衞尉竭、內史肆、佐弋竭、中大夫令齊等二十人皆梟首。","notes":[{"source":"集解","text":"縣首於木上曰梟。"},{"source":"正義","text":"梟，古堯反。懸首於木上曰梟。"}]},{"id":"a41","section":"始皇九年","anchor":"衞尉竭、內史肆、佐弋竭、中大夫令齊等二十人皆梟首。車裂以徇，滅其宗。","notes":[{"source":"正義","text":"說苑云：「秦始皇太后不謹，幸郎嫪毐，始皇取毐四支車裂之，取兩弟撲殺之，取太后遷之咸陽宮。下令曰：『以太后事諫者，戮而殺之，蒺藜其脊。』諫而死者二十七人。茅焦乃上說曰：『齊客茅焦，願以太后事諫。』皇帝曰：『走告若，不見闕下積死人耶？』使者問焦。焦曰：『陛下車裂假父，有嫉妬之心；囊撲兩弟，有不慈之名；遷母咸陽，有不孝之行；蒺藜諫士，有桀紂之治。天下聞之，盡瓦解，無向秦者。』王乃自迎太后歸咸陽，立茅焦爲傅，又爵之上卿。」《括地志》云：「茅焦，滄州人也。」"}]},{"id":"a42","section":"始皇九年","anchor":"、中大夫令齊等二十人皆梟首。車裂以徇，滅其宗。及其舍人，輕者爲鬼薪。","notes":[{"source":"集解","text":"應劭曰：「取薪給宗廟爲鬼薪也。」如淳曰：「律說鬼薪作三歲。」"},{"source":"正義","text":"言毐舍人罪重者已刑戮，輕者罰徒役三歲。"}]},{"id":"a43","section":"始皇九年","anchor":"車裂以徇，滅其宗。及其舍人，輕者爲鬼薪。及奪爵遷蜀四千餘家，家房陵。","notes":[{"source":"正義","text":"《括地志》云：「房陵即今房州房陵縣，古楚漢中郡地也。是巴蜀之境。《地理志》云房陵縣屬漢中郡，在益州部，接東南一千三百一十里也。」"}]},{"id":"a44","section":"始皇九年","anchor":"輕者爲鬼薪。及奪爵遷蜀四千餘家，家房陵。（四）〔是〕月寒凍，有死者。","notes":[{"source":"正義","text":"四月建巳之月，孟夏寒凍，民有死者，以秦法酷急，則天應之而史書之。故《尚書》洪範「急常寒若」，孔注云「君行急則常寒順之」。"}]},{"id":"a45","section":"始皇九年","anchor":"奪爵遷蜀四千餘家，家房陵。（四）〔是〕月寒凍，有死者。楊端和攻衍氏。","notes":[{"source":"索隱","text":"端和，秦將。衍氏，魏邑。"},{"source":"正義","text":"衍，羊善反。在鄭州。"}]},{"id":"a46","section":"始皇十年","anchor":"十年，","notes":[{"source":"集解","text":"徐廣曰：「甲子。」"}]},{"id":"a47","section":"始皇十年","anchor":"有遷母太后之名，恐諸侯聞之，由此倍秦也。」秦王乃迎太后於雍而入咸陽，","notes":[{"source":"集解","text":"說苑曰：「始皇帝立茅焦爲傅，又爵之上卿。太后大喜，曰『天下亢直，使敗復成，安秦社稷，使妾母子復相見者，茅君之力也』。」"}]},{"id":"a48","section":"始皇十年","anchor":"名，恐諸侯聞之，由此倍秦也。」秦王乃迎太后於雍而入咸陽，復居甘泉宮。","notes":[{"source":"集解","text":"徐廣曰：「表云咸陽南宮也。」"}]},{"id":"a49","section":"始皇十年","anchor":"。」秦王從其計，見尉繚亢禮，衣服食飲與繚同。繚曰：「秦王爲人，蜂準，","notes":[{"source":"集解","text":"徐廣曰：「蜂，一作『隆』。」"},{"source":"正義","text":"蜂，孚逢反。準，章允反。蜂，蠆也。高鼻也。文穎曰：「準，鼻也。」"}]},{"id":"a50","section":"始皇十年","anchor":"，見尉繚亢禮，衣服食飲與繚同。繚曰：「秦王爲人，蜂準，長目，摯鳥膺，","notes":[{"source":"正義","text":"鷙鳥，鶻。膺突向前，其性悍勇。"}]},{"id":"a51","section":"始皇十年","anchor":"：「秦王爲人，蜂準，長目，摯鳥膺，豺聲，少恩而虎狼心，居約易出人下，","notes":[{"source":"正義","text":"易，以豉反。言始皇居儉約之時易以謙卑。"}]},{"id":"a52","section":"始皇十年","anchor":"蜂準，長目，摯鳥膺，豺聲，少恩而虎狼心，居約易出人下，得志亦輕食人。","notes":[{"source":"正義","text":"言始皇得天下之志，亦輕易而啖食於人。"}]},{"id":"a53","section":"始皇十年","anchor":"天下，天下皆爲虜矣。不可與久游。」乃亡去。秦王覺，固止，以爲秦國尉，","notes":[{"source":"正義","text":"若漢太尉、大將軍之比也。"}]},{"id":"a54","section":"始皇十一年","anchor":"十一年，王翦、桓齮、楊端和攻鄴，取九城。王翦攻閼與、橑楊，","notes":[{"source":"集解","text":"徐廣曰：「橑音老，在并州。」"},{"source":"正義","text":"漢表在清河。《十三州志》云：「橑陽，上黨西北百八十里也。」"}]},{"id":"a55","section":"始皇十一年","anchor":"鄴，取九城。王翦攻閼與、橑楊，皆并爲一軍。翦將十八日，軍歸斗食以下，","notes":[{"source":"集解","text":"《漢書百官表》曰：「百石以下，有斗食，佐史之秩。」"},{"source":"正義","text":"一曰得斗粟爲料。"}]},{"id":"a56","section":"始皇十一年","anchor":"王翦攻閼與、橑楊，皆并爲一軍。翦將十八日，軍歸斗食以下，什推二人從軍","notes":[{"source":"索隱","text":"言王翦爲將，諸軍中皆歸斗食以下，無功佐史，什中唯推擇二人令從軍耳。"}]},{"id":"a57","section":"始皇十二年","anchor":"十二年，文信侯不韋死，竊葬。","notes":[{"source":"索隱","text":"按：不韋飲鴆死，其賓客數千人竊共葬於洛陽北芒山。"}]},{"id":"a58","section":"始皇十二年","anchor":"十二年，文信侯不韋死，竊葬。其舍人臨者，晉人也逐出之；","notes":[{"source":"正義","text":"臨，力禁反，臨哭也。若是三晉之人，逐出令歸也。"}]},{"id":"a59","section":"始皇十二年","anchor":"信侯不韋死，竊葬。其舍人臨者，晉人也逐出之；秦人六百石以上奪爵，遷；","notes":[{"source":"正義","text":"上音時掌反。若是秦人哭臨者，奪其官爵，遷移於房陵。"}]},{"id":"a60","section":"始皇十二年","anchor":"，晉人也逐出之；秦人六百石以上奪爵，遷；五百石以下不臨，遷，勿奪爵。","notes":[{"source":"正義","text":"若是秦人不哭臨不韋者，不奪官爵，亦遷移於房陵。"}]},{"id":"a61","section":"始皇十二年","anchor":"百石以下不臨，遷，勿奪爵。自今以來，操國事不道如嫪毐、不韋者籍其門，","notes":[{"source":"集解","text":"徐廣曰：「一作『文』。」"},{"source":"索隱","text":"謂藉沒其一門皆爲徒隸，後並視此爲常故也。"},{"source":"正義","text":"籍錄其子孫，禁不得仕宦。"}]},{"id":"a62","section":"始皇十三年","anchor":"十三年，桓齮攻趙平陽，","notes":[{"source":"正義","text":"《括地志》云：「平陽故城在相州臨漳縣西二十五里。」又云：「平陽，戰國時屬韓，後屬趙。」"}]},{"id":"a63","section":"始皇十三年","anchor":"十三年，桓齮攻趙平陽，殺趙將扈輒，","notes":[{"source":"正義","text":"扈音戶。輒，張獵反，趙之將軍。"}]},{"id":"a64","section":"始皇十四年","anchor":"十四年，攻趙軍於平陽，取宜安，","notes":[{"source":"正義","text":"《括地志》云：「宜安故城在常山槀城縣西南二十五里也。」"}]},{"id":"a65","section":"始皇十四年","anchor":"十四年，攻趙軍於平陽，取宜安，破之，殺其將軍。桓齮定平陽、武城。","notes":[{"source":"正義","text":"即貝州武城縣外城是也。七國時趙邑。"}]},{"id":"a66","section":"始皇十四年","anchor":"，殺其將軍。桓齮定平陽、武城。韓非使秦，秦用李斯謀，留非，非死雲陽。","notes":[{"source":"正義","text":"《括地志》云：「雲陽城在雍州雲陽縣西八十里，秦始皇甘泉宮在焉。」"}]},{"id":"a67","section":"始皇十五年","anchor":"十五年，大興兵，一軍至鄴，一軍至太原，取狼孟。","notes":[{"source":"集解","text":"《地理志》太原有狼孟縣。"}]},{"id":"a68","section":"始皇十六年","anchor":"十六年九月，發卒受地韓南陽假守","notes":[{"source":"正義","text":"假，格雅反。守音狩。"}]},{"id":"a69","section":"始皇十六年","anchor":"六年九月，發卒受地韓南陽假守騰。初令男子書年。魏獻地於秦。秦置麗邑。","notes":[{"source":"正義","text":"麗，力知反。《括地志》云：「雍州新豐縣，本周時驪戎邑。《左傳》云晉獻公伐驪戎，杜注云在京兆新豐縣，其後秦滅之以爲邑。」"}]},{"id":"a70","section":"始皇十七年","anchor":"十七年，內史騰攻韓，得韓王安，盡納其地，","notes":[{"source":"正義","text":"韓王安之九年，秦盡滅之。"}]},{"id":"a71","section":"始皇十八年","anchor":"十八年，","notes":[{"source":"集解","text":"徐廣曰：「巴郡出大人，長二十五丈六尺。」"}]},{"id":"a72","section":"始皇十八年","anchor":"十八年，大興兵攻趙，王翦將上地，","notes":[{"source":"正義","text":"上郡上縣，今綏州等是也。"}]},{"id":"a73","section":"始皇十八年","anchor":"十八年，大興兵攻趙，王翦將上地，下井陘，","notes":[{"source":"集解","text":"服虔曰：「山名，在常山。今爲縣。音刑。」"}]},{"id":"a74","section":"始皇十八年","anchor":"十八年，大興兵攻趙，王翦將上地，下井陘，端和將河內，羌瘣","notes":[{"source":"正義","text":"胡罪反。"}]},{"id":"a75","section":"始皇十九年","anchor":"十九年，王翦、羌瘣盡定取趙地東陽，得趙王。","notes":[{"source":"索隱","text":"趙王遷也。"},{"source":"正義","text":"趙幽繆王遷八年，秦取趙地至平陽。平陽在貝州歷亭縣界。遷王於房陵。"}]},{"id":"a76","section":"始皇二十年","anchor":"二十年，燕太子丹患秦兵至國，恐，使荊軻刺秦王。秦王覺之，體解","notes":[{"source":"正義","text":"紀買反。"}]},{"id":"a77","section":"始皇二十一年","anchor":"二十一年，王賁","notes":[{"source":"正義","text":"音奔。"}]},{"id":"a78","section":"始皇二十一年","anchor":"詣王翦軍，遂破燕太子軍，取燕薊城，得太子丹之首。燕王東收遼東而王之。","notes":[{"source":"正義","text":"王，于放反。"}]},{"id":"a79","section":"始皇二十一年","anchor":"首。燕王東收遼東而王之。王翦謝病老歸。新鄭反。昌平君徙於郢。大雨雪，","notes":[{"source":"正義","text":"雨，于遇反。"}]},{"id":"a80","section":"始皇二十二年","anchor":"二十二年，王賁攻魏，引河溝灌大梁，大梁城壞，其王請降，","notes":[{"source":"索隱","text":"魏王假也。"}]},{"id":"a81","section":"始皇二十三年","anchor":"二十三年，秦王復召王翦，彊起之，使將擊荊。","notes":[{"source":"正義","text":"秦號楚爲荊者，以莊襄王名子楚，諱之，故言荊也。"}]},{"id":"a82","section":"始皇二十三年","anchor":"二十三年，秦王復召王翦，彊起之，使將擊荊。取陳以南至平輿，","notes":[{"source":"集解","text":"《地理志》汝南有平輿縣。"},{"source":"正義","text":"輿音餘。平輿，豫州縣也。"}]},{"id":"a83","section":"始皇二十三年","anchor":"二十三年，秦王復召王翦，彊起之，使將擊荊。取陳以南至平輿，虜荊王。","notes":[{"source":"索隱","text":"荊王負芻也。楚稱荊者，以避莊襄王諱，故易之也。"}]},{"id":"a84","section":"始皇二十三年","anchor":"南至平輿，虜荊王。秦王游至郢陳。荊將項燕立昌平君爲荊王，反秦於淮南。","notes":[{"source":"集解","text":"徐廣曰：「淮，一作『江』。」"},{"source":"正義","text":"昌平也。楚淮北之地盡入於秦。"}]},{"id":"a85","section":"始皇二十五年","anchor":"二十五年，大興兵，使王賁將，攻燕遼東，得燕王喜。","notes":[{"source":"正義","text":"燕王喜之五十三年，燕亡。"}]},{"id":"a86","section":"始皇二十五年","anchor":"，使王賁將，攻燕遼東，得燕王喜。還攻代，虜代王嘉。王翦遂定荊江南地；","notes":[{"source":"正義","text":"言王翦遂平定楚及江南地，降越君，置爲會稽郡。"}]},{"id":"a87","section":"始皇二十五年","anchor":"將，攻燕遼東，得燕王喜。還攻代，虜代王嘉。王翦遂定荊江南地；降越君，","notes":[{"source":"正義","text":"降，閑江反。楚威王已滅〔越〕，其餘自稱君長，今降秦。"}]},{"id":"a88","section":"始皇二十五年","anchor":"攻代，虜代王嘉。王翦遂定荊江南地；降越君，置會稽郡。五月，天下大酺。","notes":[{"source":"正義","text":"服虔曰：「酺音蒲。」文穎曰：「酺，《周禮》族師掌春秋祭酺，爲人物災害之神。」蘇林曰：「陳留俗，三月上巳水上飲食爲酺。」"},{"source":"正義","text":"天下歡樂大飲酒也。秦既平韓、趙、魏、燕、楚五國，故天下大酺也。"}]},{"id":"a89","section":"始皇二十六年","anchor":"二十六年，齊王建與其相后勝","notes":[{"source":"正義","text":"音升，齊相姓名。"}]},{"id":"a90","section":"始皇二十六年","anchor":"建與其相后勝發兵守其西界，不通秦。秦使將軍王賁從燕南攻齊，得齊王建。","notes":[{"source":"索隱","text":"六國皆滅也。十七年得韓王安，十九年得趙王遷，二十二年魏王假降，二十三年虜荊王負芻，二十五年得燕王喜，二十六年得齊王建。"},{"source":"正義","text":"齊王建之三十四年，齊國亡。"}]},{"id":"a91","section":"始皇二十六年","anchor":"秦初并天下，令丞相、御史曰：","notes":[{"source":"正義","text":"令，力政反。乃今之赦令、赦書。"}]},{"id":"a92","section":"始皇二十六年","anchor":"秦初并天下，令丞相、御史曰：「異日韓王納地效璽，","notes":[{"source":"正義","text":"效猶至見。"}]},{"id":"a93","section":"始皇二十六年","anchor":"，虜其王。寡人以爲善，庶幾息兵革。趙王使其相李牧來約盟，故歸其質子。","notes":[{"source":"正義","text":"質音致。"}]},{"id":"a94","section":"始皇二十六年","anchor":"王始約服入秦，已而與韓、趙謀襲秦，秦兵吏誅，遂破之。荊王獻青陽以西，","notes":[{"source":"集解","text":"《漢書》鄒陽傳曰：「越水長沙，還舟青陽。」張晏曰：「青陽，地名。」蘇林曰：「青陽，長沙縣是也。」"}]},{"id":"a95","section":"始皇二十六年","anchor":"定。今名號不更，無以稱成功，傳後世。其議帝號。」丞相綰、御史大夫劫、","notes":[{"source":"集解","text":"《漢書百官表》曰：「御史大夫，秦官。」應劭曰：「侍御史之率，故稱大夫也。」"},{"source":"索隱","text":"綰姓王。劫姓馮。"}]},{"id":"a96","section":"始皇二十六年","anchor":"號不更，無以稱成功，傳後世。其議帝號。」丞相綰、御史大夫劫、廷尉斯等","notes":[{"source":"集解","text":"《漢書百官表》曰：「廷尉，秦官。」應劭曰：「聽獄必質諸朝廷，與眾共之，兵獄同制，故稱廷尉。」"}]},{"id":"a97","section":"始皇二十六年","anchor":"曰：「昔者五帝地方千里，其外侯服夷服諸侯或朝或否，天子不能制。今陛下","notes":[{"source":"集解","text":"蔡邕曰：「陛，階也，所由升堂也。天子必有近臣立於陛側，以戒不虞。謂之『陛下』者，羣臣與天子言，不敢指斥，故呼在陛下者與之言，因卑達尊之意也。上書亦如之。」"}]},{"id":"a98","section":"始皇二十六年","anchor":"侯或朝或否，天子不能制。今陛下興義兵，誅殘賊，平定天下，海內爲郡縣，","notes":[{"source":"正義","text":"郡，人所羣聚也。"}]},{"id":"a99","section":"始皇二十六年","anchor":"爲郡縣，法令由一統，自上古以來未嘗有，五帝所不及。臣等謹與博士議曰：","notes":[{"source":"集解","text":"《漢書百官表》曰：「博士，秦官，掌通古今。」"}]},{"id":"a100","section":"始皇二十六年","anchor":"來未嘗有，五帝所不及。臣等謹與博士議曰：『古有天皇，有地皇，有泰皇，","notes":[{"source":"索隱","text":"按：天皇、地皇之下即云泰皇，當人皇也。而《封禪書》云「昔者太帝使素女鼓瑟而悲」，蓋三皇已前稱泰皇。一云泰皇，太昊也。"}]},{"id":"a101","section":"始皇二十六年","anchor":"，泰皇最貴。』臣等昧死上尊號，王爲『泰皇』。命爲『制』，令爲『詔』，","notes":[{"source":"集解","text":"蔡邕曰：「制書，帝者制度之命也，其文曰『制』。詔，詔書。詔，告也。」"},{"source":"正義","text":"令音力政反。制詔三代無文，秦始有之。"}]},{"id":"a102","section":"始皇二十六年","anchor":"死上尊號，王爲『泰皇』。命爲『制』，令爲『詔』，天子自稱曰『朕』。」","notes":[{"source":"集解","text":"蔡邕曰：「朕，我也。古者上下共稱之，貴賤不嫌，則可以同號之義也。皋陶與舜言『朕言惠，可底行』。屈原曰『朕皇考』。至秦，然後天子獨以爲稱。漢因而不改。」"}]},{"id":"a103","section":"始皇二十六年","anchor":"皇』。命爲『制』，令爲『詔』，天子自稱曰『朕』。」王曰：「去『泰』，","notes":[{"source":"正義","text":"去音丘呂反。"}]},{"id":"a104","section":"始皇二十六年","anchor":"，著『皇』，采上古『帝』位號，號曰『皇帝』。他如議。」制曰：「可。」","notes":[{"source":"集解","text":"蔡邕曰：「羣臣有所奏，請尚書令奏之，下有司曰『制』，天子答之曰『可』。」"}]},{"id":"a105","section":"始皇二十六年","anchor":"帝』位號，號曰『皇帝』。他如議。」制曰：「可。」追尊莊襄王爲太上皇。","notes":[{"source":"集解","text":"漢高祖尊父曰太上皇，亦放此也。"}]},{"id":"a106","section":"始皇二十六年","anchor":"。如此，則子議父，臣議君也，甚無謂，朕弗取焉。自今已來，除《謚法》。","notes":[{"source":"集解","text":"《謚法》，周公所作。"}]},{"id":"a107","section":"始皇二十六年","anchor":"也，甚無謂，朕弗取焉。自今已來，除《謚法》。朕爲始皇帝。後世以計數，","notes":[{"source":"正義","text":"色主反。"}]},{"id":"a108","section":"始皇二十六年","anchor":"始皇推終始五德之傳，","notes":[{"source":"集解","text":"鄭玄曰：「音亭傳。」"},{"source":"索隱","text":"音張戀反。傳，次也。謂五行之德始終相次也。《漢書郊祀志》曰：「齊人鄒子之徒論著終始五德之運，始皇采用。」"}]},{"id":"a109","section":"始皇二十六年","anchor":"始皇推終始五德之傳，以爲周得火德，秦代周德，從所不勝。","notes":[{"source":"正義","text":"勝，申證反。秦以周爲火德。能滅火者水也，故稱從其所不勝於秦。"}]},{"id":"a110","section":"始皇二十六年","anchor":"始皇推終始五德之傳，以爲周得火德，秦代周德，從所不勝。方今水德之始，","notes":[{"source":"索隱","text":"《封禪書》曰秦文公獲黑龍，以爲水瑞，秦始皇帝因自謂爲水德也。"}]},{"id":"a111","section":"始皇二十六年","anchor":"周得火德，秦代周德，從所不勝。方今水德之始，改年始，朝賀皆自十月朔。","notes":[{"source":"正義","text":"周以建子之月爲正，秦以建亥之月爲正，故其年始用十月而朝賀。"}]},{"id":"a112","section":"始皇二十六年","anchor":"代周德，從所不勝。方今水德之始，改年始，朝賀皆自十月朔。衣服旄旌節旗","notes":[{"source":"正義","text":"旌音精。旄音毛。旗音其。周《禮》云：「析羽爲旌，熊虎爲旗。」旌節者，編毛爲之，以象竹節，《漢書》云「蘇武執節在匈奴牧羊，節毛盡落」是也。韋昭云：「節者，山國用人節，澤國用龍節，皆以金爲之。道路以旌節，門關用符節，都鄙用管節，皆用竹爲之。」"}]},{"id":"a113","section":"始皇二十六年","anchor":"從所不勝。方今水德之始，改年始，朝賀皆自十月朔。衣服旄旌節旗皆上黑。","notes":[{"source":"正義","text":"以水德屬北方，故上黑。"}]},{"id":"a114","section":"始皇二十六年","anchor":"節旗皆上黑。數以六爲紀，符、法冠皆六寸，而輿六尺，六尺爲步，乘六馬。","notes":[{"source":"集解","text":"張晏曰：「水，北方，黑，終數六，故以六寸爲符，六尺爲步。」瓚曰：「水數六，故以六爲名。」譙周曰：「步以人足爲數，非獨秦制然。」"},{"source":"索隱","text":"管子司馬法皆云六尺爲步。譙周以爲步以人足，非獨秦制。又按：《禮記》王制曰「古者八尺爲步」，今以周尺六尺四寸爲步，步之尺數亦不同。"}]},{"id":"a115","section":"始皇二十六年","anchor":"以爲水德之始。剛毅戾深，事皆決於法，刻削毋仁恩和義，然後合五德之數。","notes":[{"source":"索隱","text":"水主陰，陰刑殺，故急法刻削，以合五德之數。"}]},{"id":"a116","section":"始皇二十六年","anchor":"丞相綰等言：「諸侯初破，燕、齊、荊地遠，不爲","notes":[{"source":"正義","text":"于僞反。"}]},{"id":"a117","section":"始皇二十六年","anchor":"神靈一統，皆爲郡縣，諸子功臣以公賦稅重賞賜之，甚足易制。天下無異意，","notes":[{"source":"正義","text":"易音以職反。"}]},{"id":"a118","section":"始皇二十六年","anchor":"分天下以爲三十六郡，","notes":[{"source":"集解","text":"三十六郡者，三川、河東、南陽、南郡、九江、鄣郡、會稽、潁川、碭郡、泗水、薛郡、東郡、琅邪、齊郡、上谷、漁陽、右北平、遼西、遼東、代郡、鉅鹿、邯鄲、上黨、太原、雲中、九原、鴈門、上郡、隴西、北地、漢中、巴郡、蜀郡、黔中、長沙凡三十五，與內史爲三十六郡。"},{"source":"正義","text":"風俗通云：「周制天子方千里，分爲百縣，縣有四郡，故《左傳》云上大夫受縣，下大夫受郡。秦始皇初置三十六郡以監縣也。」"}]},{"id":"a119","section":"始皇二十六年","anchor":"分天下以爲三十六郡，郡置守、尉、監。","notes":[{"source":"集解","text":"《漢書百官表》曰：「秦郡守掌治其郡；有丞、尉，掌佐守典武職甲卒；監御史掌監郡。」"}]},{"id":"a120","section":"始皇二十六年","anchor":"分天下以爲三十六郡，郡置守、尉、監。更名民曰「黔首」。","notes":[{"source":"集解","text":"應劭曰：「黔亦黎，黑也。」"}]},{"id":"a121","section":"始皇二十六年","anchor":"天下以爲三十六郡，郡置守、尉、監。更名民曰「黔首」。大酺。收天下兵，","notes":[{"source":"集解","text":"應劭曰：「古者以銅爲兵。」"}]},{"id":"a122","section":"始皇二十六年","anchor":"守、尉、監。更名民曰「黔首」。大酺。收天下兵，聚之咸陽，銷以爲鍾鐻，","notes":[{"source":"集解","text":"徐廣曰：「音巨。」"}]},{"id":"a123","section":"始皇二十六年","anchor":"「黔首」。大酺。收天下兵，聚之咸陽，銷以爲鍾鐻，金人十二，重各千石，","notes":[{"source":"索隱","text":"按：二十六年，有長人見于臨洮，故銷兵器，鑄而象之。謝承《後漢書》「銅人，翁仲，翁仲其名也」。三輔舊事「銅人十二，各重三十四萬斤。漢代在長樂宮門前」。董卓壞其十爲錢，餘二猶在。石季龍徙之鄴，苻堅又徙長安而銷之也。"},{"source":"正義","text":"《漢書》五行志云：「二十六年，有大人長五丈，足履六尺，皆夷狄服，凡十二人，見于臨洮，故銷兵器，鑄而象之。」謝承《後漢書》云：「銅人，翁仲其名也。」三輔舊事云：「聚天下兵器，鑄銅人十二，各重二十四萬斤。漢世在長樂宮門。」魏志董卓傳云：「椎破銅人十及鍾鐻，以鑄小錢。」《關中記》云：「董卓壞銅人，餘二枚，徙清門裏。魏明帝欲將詣洛，載到霸城，重不可致。後石季龍徙之鄴，苻堅又徙入長安而銷之。」英雄記云：「昔大人見臨洮而銅人鑄，至董卓而銅人毀也。」"}]},{"id":"a124","section":"始皇二十六年","anchor":"各千石，置廷宮中。一法度衡石丈尺。車同軌。書同文字。地東至海暨朝鮮，","notes":[{"source":"正義","text":"暨，其記反。朝音潮。鮮音仙。海謂渤海南至揚、蘇、台等州之東海也。暨，及也。東北朝鮮國。《括地志》云：「高驪治平壤城，本漢樂浪郡王險城，即古朝鮮也。」"}]},{"id":"a125","section":"始皇二十六年","anchor":"。一法度衡石丈尺。車同軌。書同文字。地東至海暨朝鮮，西至臨洮、羌中，","notes":[{"source":"正義","text":"洮，吐高反。《括地志》云：「臨洮郡即今洮州，亦古西羌之地，在京西千五百五十一里羌中。從臨洮西南芳州扶松府以西，並古諸羌地也。」"}]},{"id":"a126","section":"始皇二十六年","anchor":"丈尺。車同軌。書同文字。地東至海暨朝鮮，西至臨洮、羌中，南至北嚮戶，","notes":[{"source":"集解","text":"吳都賦曰：「開北戶以向日。」劉逵曰：「日南之北戶，猶日北之南戶也。」"}]},{"id":"a127","section":"始皇二十六年","anchor":"東至海暨朝鮮，西至臨洮、羌中，南至北嚮戶，北據河爲塞，並陰山至遼東。","notes":[{"source":"集解","text":"《地理志》西河有陰山縣。"},{"source":"正義","text":"塞，先代反。並，白浪反。謂靈、夏、勝等州之北黃河。陰山在朔州北塞外。從河傍陰山，東至遼東，築長城爲北界。"}]},{"id":"a128","section":"始皇二十六年","anchor":"。諸廟及章臺、上林皆在渭南。秦每破諸侯，寫放其宮室，作之咸陽北阪上，","notes":[{"source":"集解","text":"徐廣曰：「在長安西北，漢武時別名渭城。」"},{"source":"正義","text":"今咸陽縣北阪上。"}]},{"id":"a129","section":"始皇二十六年","anchor":"上林皆在渭南。秦每破諸侯，寫放其宮室，作之咸陽北阪上，南臨渭，自雍門","notes":[{"source":"集解","text":"徐廣曰：「在高陵縣。」"},{"source":"正義","text":"今岐州雍縣東。"}]},{"id":"a130","section":"始皇二十六年","anchor":"宮室，作之咸陽北阪上，南臨渭，自雍門以東至涇、渭，殿屋複道周閣相屬。","notes":[{"source":"正義","text":"複音福。屬，之欲反。廟記云：「北至九嵏、甘泉，南至長楊、五柞，東至河，西至汧渭之交，東西八百里，離宮別館相望屬也。木衣綈繡，土被朱紫，宮人不徙。窮年忘歸，猶不能遍也。」"}]},{"id":"a131","section":"始皇二十六年","anchor":"，自雍門以東至涇、渭，殿屋複道周閣相屬。所得諸侯美人鍾鼓，以充入之。","notes":[{"source":"正義","text":"三輔舊事云：「始皇表河以爲秦東門，表汧以爲秦西門，表中外殿觀百四十五，後宮列女萬餘人，氣上衝于天。」"}]},{"id":"a132","section":"始皇二十七年","anchor":"二十七年，始皇巡隴西、北地，","notes":[{"source":"正義","text":"隴西，今隴右；北地，今寧州也。"}]},{"id":"a133","section":"始皇二十七年","anchor":"二十七年，始皇巡隴西、北地，出雞頭山，","notes":[{"source":"正義","text":"《括地志》云：「雞頭山在成州上祿縣東北二十里，在京西南九百六十里。酈元云蓋大隴山異名也。《後漢書》隗囂傳云『王莽塞雞頭』，即此也。」按：原州平高縣西百里亦有笄頭山，在京西北八百里，黃帝雞山之所。"}]},{"id":"a134","section":"始皇二十七年","anchor":"二十七年，始皇巡隴西、北地，出雞頭山，過回中。","notes":[{"source":"集解","text":"應劭曰：「回中在安定高平。」孟康曰：「回中在北地。」"},{"source":"正義","text":"《括地志》云：「回中宮在岐州雍縣西四十里。」言始皇欲西巡隴西之北，從咸陽向西北出寧州，西南行至成州，出雞頭山，東還，過岐州回中宮。"}]},{"id":"a135","section":"始皇二十七年","anchor":"西、北地，出雞頭山，過回中。焉作信宮渭南，已更命信宮爲極廟，象天極。","notes":[{"source":"索隱","text":"爲宮廟象天極，故曰極廟。《天官書》曰「中宮曰天極」是也。"}]},{"id":"a136","section":"始皇二十七年","anchor":"渭南，已更命信宮爲極廟，象天極。自極廟道通酈山，作甘泉前殿。築甬道，","notes":[{"source":"集解","text":"應劭曰：「築垣牆如街巷。」"},{"source":"正義","text":"築音竹。甬音勇。應劭云：「謂於馳道外築牆，天子於中行，外人不見。」"}]},{"id":"a137","section":"始皇二十七年","anchor":"廟道通酈山，作甘泉前殿。築甬道，自咸陽屬之。是歲，賜爵一級。治馳道。","notes":[{"source":"集解","text":"應劭曰：「馳道，天子道也，道若今之中道然。」《漢書》賈山傳曰：「秦爲馳道於天下，東窮燕齊，南極吳楚，江湖之上，濱海之觀畢至。道廣五十步，三丈而樹，厚築其外，隱以金椎，樹以青松。」"}]},{"id":"a138","section":"始皇二十八年","anchor":"二十八年，始皇東行郡縣，上鄒嶧山。","notes":[{"source":"集解","text":"韋昭曰：「鄒，魯縣，山在其北。」"},{"source":"正義","text":"上，時掌反。鄒，側留反。嶧音亦。國系云：「邾嶧山亦名鄒山，在兗州鄒縣南三十二里。魯穆公改『邾』作『鄒』，其山遂從『邑』變。山北去黃河三百餘里。」"}]},{"id":"a139","section":"始皇二十八年","anchor":"郡縣，上鄒嶧山。立石，與魯諸儒生議，刻石頌秦德，議封禪望祭山川之事。","notes":[{"source":"正義","text":"晉太康地記云：「爲壇於太山以祭天，示增高也。爲墠於梁父以祭地，示增廣也。祭尚玄酒而俎魚。墠皆廣長十二丈。壇高三尺，階三等，而樹石太山之上，高三丈一尺，廣三尺，秦之刻石云。」"}]},{"id":"a140","section":"始皇二十八年","anchor":"山。立石，與魯諸儒生議，刻石頌秦德，議封禪望祭山川之事。乃遂上泰山，","notes":[{"source":"正義","text":"泰山一曰岱宗，東嶽也，在兗州博城縣西北三十里。《山海經》云：「泰山，其上多玉，其下多石。」郭璞云：「從泰山下至山頭，百四十八里三百步。」道書福地記云：「泰山高四千九百丈二尺，周迴二千里。多芝草玉石，長津甘泉，仙人室。又有地獄六，曰鬼神之府，從西上，下有洞天，周迴三千里，鬼神考讁之府。」"}]},{"id":"a141","section":"始皇二十八年","anchor":"儒生議，刻石頌秦德，議封禪望祭山川之事。乃遂上泰山，立石，封，祠祀。","notes":[{"source":"集解","text":"服虔曰：「增天之高，歸功於天。」張晏曰：「天高不可及，於泰山上立封禪而祭之，冀近神靈也。」瓚曰：「積土爲封。謂負土於泰山上，爲壇而祭之。」"}]},{"id":"a142","section":"始皇二十八年","anchor":"遂上泰山，立石，封，祠祀。下，風雨暴至，休於樹下，因封其樹爲五大夫。","notes":[{"source":"正義","text":"封，一作「復」，音福。"}]},{"id":"a143","section":"始皇二十八年","anchor":"，立石，封，祠祀。下，風雨暴至，休於樹下，因封其樹爲五大夫。禪梁父。","notes":[{"source":"集解","text":"服虔曰：「禪，闡廣土地也。」瓚曰：「古者聖王封泰山，禪亭亭或梁父，皆泰山下小山。除地爲墠，祭於梁父。後改『墠』曰『禪』。」正義父音甫。在兗州泗水縣北八十里。"}]},{"id":"a144","section":"始皇二十八年","anchor":"下，風雨暴至，休於樹下，因封其樹爲五大夫。禪梁父。刻所立石，其辭曰：","notes":[{"source":"索隱","text":"其詞每三句爲韻，凡十二韻。下之罘、碣石、會稽三銘皆然。"}]},{"id":"a145","section":"始皇二十八年","anchor":"皇帝臨位，作制明法，臣下脩飭。","notes":[{"source":"正義","text":"飭音勅。"}]},{"id":"a146","section":"始皇二十八年","anchor":"年，初并天下，罔不賓服。親巡遠方黎民，登茲泰山，周覽東極。從臣思迹，","notes":[{"source":"正義","text":"從，財用反。"}]},{"id":"a147","section":"始皇二十八年","anchor":"服。親巡遠方黎民，登茲泰山，周覽東極。從臣思迹，本原事業，祗誦功德。","notes":[{"source":"正義","text":"祗音脂。"}]},{"id":"a148","section":"始皇二十八年","anchor":"于後世，順承勿革。皇帝躬聖，既平天下，不懈於治。夙興夜寐，建設長利，","notes":[{"source":"正義","text":"長，直良反。"}]},{"id":"a149","section":"始皇二十八年","anchor":"經宣達，遠近畢理，咸承聖志。貴賤分明，男女禮順，慎遵職事。昭隔內外，","notes":[{"source":"集解","text":"徐廣曰：「隔，一作『融』。」"}]},{"id":"a150","section":"始皇二十八年","anchor":"於是乃並勃海以東，","notes":[{"source":"正義","text":"並，白浪反。勃作「渤」，蒲忽反。"}]},{"id":"a151","section":"始皇二十八年","anchor":"於是乃並勃海以東，過黃、腄，","notes":[{"source":"集解","text":"《地理志》東萊有黃縣、腄縣。"},{"source":"正義","text":"腄，逐瑞反。字或作「陲」。《括地志》云：「黃縣故城在萊州黃縣東南二十五里，古萊子國也。牟平縣城在黃縣南百三十里。《十三州志》云牟平縣古腄縣也。」"}]},{"id":"a152","section":"始皇二十八年","anchor":"於是乃並勃海以東，過黃、腄，窮成山，登之罘，","notes":[{"source":"集解","text":"《地理志》之罘山在腄縣。"},{"source":"正義","text":"罘音浮。《括地志》云：「在萊州文登縣東北百八十里。成山在文登縣西北百九十里。」窮猶登極也。《封禪書》云：「八神，五曰陽主；祠之罘；七曰日主，祠成山，成山斗入海。」又云：「之罘山在海中。文登縣，古腄縣也。」"}]},{"id":"a153","section":"始皇二十八年","anchor":"南登琅邪，","notes":[{"source":"集解","text":"今兗州東沂州、密州，即古琅邪也。"}]},{"id":"a154","section":"始皇二十八年","anchor":"南登琅邪，大樂之，留三月。乃徙黔首三萬戶琅邪臺下，","notes":[{"source":"集解","text":"《地理志》越王句踐嘗治琅邪縣，起臺館。"},{"source":"索隱","text":"《山海經》琅邪臺在渤海閒。蓋海畔有山，形如臺，在琅邪，故曰琅邪臺。"},{"source":"正義","text":"《括地志》云：「密州諸城縣東南百七十里有琅邪臺，越王句踐觀臺也。臺西北十里有琅邪故城。吳越春秋云：『越王句踐二十五年，徙都琅邪，立觀臺以望東海，遂號令秦、晉、齊、楚，以尊輔周室，歃血盟。』即句踐起臺處。」《括地志》云：「琅邪山在密州諸城縣東南百四十里。始皇立層臺於山上，謂之琅邪臺，孤立眾山之上。秦王樂之，留三月，立石山上，頌秦德也。」"}]},{"id":"a155","section":"始皇二十八年","anchor":"南登琅邪，大樂之，留三月。乃徙黔首三萬戶琅邪臺下，復十二歲。","notes":[{"source":"正義","text":"復音福。復三萬戶徙臺下者。"}]},{"id":"a156","section":"始皇二十八年","anchor":"登琅邪，大樂之，留三月。乃徙黔首三萬戶琅邪臺下，復十二歲。作琅邪臺，","notes":[{"source":"正義","text":"今琅邪臺。"}]},{"id":"a157","section":"始皇二十八年","anchor":"黔首三萬戶琅邪臺下，復十二歲。作琅邪臺，立石刻，頌秦德，明得意。曰：","notes":[{"source":"索隱","text":"二句爲韻。"}]},{"id":"a158","section":"始皇二十八年","anchor":"物之紀。以明人事，合同父子。聖智仁義，顯白道理。東撫東土，以省卒士。","notes":[{"source":"正義","text":"省，山井反。卒，子忽反。"}]},{"id":"a159","section":"始皇二十八年","anchor":"臨于海。皇帝之功，勤勞本事。上農除末，黔首是富。普天之下，摶心揖志。","notes":[{"source":"索隱","text":"摶，古「專」字。《左傳》云：「如琴瑟之摶壹。」揖音集。"}]},{"id":"a160","section":"始皇二十八年","anchor":"帝之功，勤勞本事。上農除末，黔首是富。普天之下，摶心揖志。器械一量，","notes":[{"source":"正義","text":"內成曰器，甲冑兜鍪之屬。外成曰械，戈矛弓戟之屬。壹量者，同度量也。"}]},{"id":"a161","section":"始皇二十八年","anchor":"輿所載。皆終其命，莫不得意。應時動事，是維皇帝。匡飭異俗，陵水經地。","notes":[{"source":"正義","text":"陵作「凌」，猶歷也。經，界也。"}]},{"id":"a162","section":"始皇二十八年","anchor":"維皇帝。匡飭異俗，陵水經地。憂恤黔首，朝夕不懈。除疑定法，咸知所辟。","notes":[{"source":"正義","text":"音避。"}]},{"id":"a163","section":"始皇二十八年","anchor":"水經地。憂恤黔首，朝夕不懈。除疑定法，咸知所辟。方伯分職，諸治經易。","notes":[{"source":"正義","text":"易音以豉反。言方伯分職治，所理常在平易。"}]},{"id":"a164","section":"始皇二十八年","anchor":"夕不懈。除疑定法，咸知所辟。方伯分職，諸治經易。舉錯必當，莫不如畫。","notes":[{"source":"正義","text":"畫音戶卦反。謂政理齊整，分明若畫，無邪惡。"}]},{"id":"a165","section":"始皇二十八年","anchor":"治經易。舉錯必當，莫不如畫。皇帝之明，臨察四方。尊卑貴賤，不踰次行。","notes":[{"source":"正義","text":"音胡郎反。"}]},{"id":"a166","section":"始皇二十八年","anchor":"卑貴賤，不踰次行。姦邪不容，皆務貞良。細大盡力，莫敢怠荒。遠邇辟隱，","notes":[{"source":"正義","text":"辟，匹亦反。"}]},{"id":"a167","section":"始皇二十八年","anchor":"定四極。誅亂除害，興利致福。節事以時，諸產繁殖。黔首安寧，不用兵革。","notes":[{"source":"正義","text":"協韻音棘。"}]},{"id":"a168","section":"始皇二十八年","anchor":"親相保，終無寇賊。驩欣奉教，盡知法式。六合之內，皇帝之土。西涉流沙，","notes":[{"source":"正義","text":"解見夏紀。"}]},{"id":"a169","section":"始皇二十八年","anchor":"知法式。六合之內，皇帝之土。西涉流沙，南盡北戶。東有東海，北過大夏。","notes":[{"source":"索隱","text":"協韻音戶。下「無不臣者」音渚。「澤及牛馬」音姥。"},{"source":"正義","text":"杜預云：「大夏，太原晉陽縣。」按：在今并州，「遷實沈於大夏，主參」，即此也。"}]},{"id":"a170","section":"始皇二十八年","anchor":"維秦王兼有天下，立名爲皇帝，乃撫東土，至于琅邪。列侯","notes":[{"source":"集解","text":"張晏曰：「列侯者，見序列。」"}]},{"id":"a171","section":"始皇二十八年","anchor":"立名爲皇帝，乃撫東土，至于琅邪。列侯武城侯王離、列侯通武侯王賁、倫侯","notes":[{"source":"索隱","text":"爵卑於列侯，無封邑者。倫，類也，亦列侯之類。"}]},{"id":"a172","section":"始皇二十八年","anchor":"武侯王賁、倫侯建成侯趙亥、倫侯昌武侯成、倫侯武信侯馮毋擇、丞相隗林、","notes":[{"source":"索隱","text":"隗姓，林名。有本作「狀」者，非。顏之推云：「隋開皇初，京師穿地得鑄秤權，有銘，云始皇時量器，丞相隗狀、王綰二人列名，其作『狀』貌之字，時令校寫，親所按驗。」王劭亦云然。斯遠古之證也。"},{"source":"正義","text":"隗音五罪反。"}]},{"id":"a173","section":"始皇二十八年","anchor":"侯馮毋擇、丞相隗林、丞相王綰、卿李斯、卿王戊、五大夫趙嬰、五大夫楊樛","notes":[{"source":"正義","text":"音居虬反。"}]},{"id":"a174","section":"始皇二十八年","anchor":"擇、丞相隗林、丞相王綰、卿李斯、卿王戊、五大夫趙嬰、五大夫楊樛從，與","notes":[{"source":"正義","text":"上才用反。下音預。言王離以下十人從始皇，咸與始皇議功德於海上，立石於琅邪臺下，十人名字並刻頌。"}]},{"id":"a175","section":"始皇二十八年","anchor":"林、丞相王綰、卿李斯、卿王戊、五大夫趙嬰、五大夫楊樛從，與議於海上。","notes":[{"source":"正義","text":"此頌前後序兩句爲韻，此三句爲韻。"}]},{"id":"a176","section":"始皇二十八年","anchor":"、五大夫趙嬰、五大夫楊樛從，與議於海上。曰：「古之帝者，地不過千里，","notes":[{"source":"正義","text":"過音戈。千里謂王畿。"}]},{"id":"a177","section":"始皇二十八年","anchor":"止，猶刻金石，以自爲紀。古之五帝三王，知教不同，法度不明，假威鬼神，","notes":[{"source":"正義","text":"言五帝、三王假借鬼神之威，以欺服遠方之民，若萇弘之比也。"}]},{"id":"a178","section":"始皇二十八年","anchor":"紀。古之五帝三王，知教不同，法度不明，假威鬼神，以欺遠方，實不稱名，","notes":[{"source":"正義","text":"稱，尺證反。"}]},{"id":"a179","section":"始皇二十八年","anchor":"既已，齊人徐巿等上書，言海中有三神山，名曰蓬萊、方丈、瀛洲，","notes":[{"source":"正義","text":"《漢書郊祀志》云：「此三神山者，其傳在渤海中，去人不遠，蓋曾有至者，諸仙人及不死之藥皆在焉。其物禽獸盡白，而黃金白銀爲宮闕。未至，望之如雲；及至，三神山乃居水下；臨之，患且至，風輒引船而去，終莫能至云。世主莫不甘心焉。」"}]},{"id":"a180","section":"始皇二十八年","anchor":"居之。請得齋戒，與童男女求之。於是遣徐巿發童男女數千人，入海求僊人。","notes":[{"source":"正義","text":"《括地志》云：「亶洲在東海中，秦始皇使徐福將童男女入海求仙人，止在此州，共數萬家。至今洲上人有至會稽市易者。吳人外國圖云亶洲去琅邪萬里。」"}]},{"id":"a181","section":"始皇二十八年","anchor":"始皇還，過彭城，","notes":[{"source":"正義","text":"彭城，徐州所理縣也。州東外城，古之彭國也。《搜神記》云陸終弟三子曰籛鏗，封於彭，爲商伯。外傳云殷末，滅彭祖氏。"}]},{"id":"a182","section":"始皇二十八年","anchor":"齋戒禱祠，欲出周鼎泗水。使千人沒水求之，弗得。乃西南渡淮水，之衡山、","notes":[{"source":"正義","text":"《括地志》云：「衡山，一名岣嶁山，在衡州湘潭縣西四十一里。」岣音苟。嶁音樓。"}]},{"id":"a183","section":"始皇二十八年","anchor":"祠，欲出周鼎泗水。使千人沒水求之，弗得。乃西南渡淮水，之衡山、南郡。","notes":[{"source":"正義","text":"今荊州也。言欲向衡山，即西北過南郡，入武關至咸陽。"}]},{"id":"a184","section":"始皇二十八年","anchor":"。使千人沒水求之，弗得。乃西南渡淮水，之衡山、南郡。浮江，至湘山祠。","notes":[{"source":"正義","text":"《括地志》云：「黃陵廟在岳州湘陰縣北五十七里，舜二妃之神。二妃冢在湘陰北一百六十里青草山上。盛弘之荊州記云青草湖南有青草山，湖因山名焉。《列女傳》云舜陟方，死於蒼梧。二妃死於江湘之閒，因葬焉。」按：湘山者，乃青草山。山近湘水，廟在山南，故言湘山祠。"}]},{"id":"a185","section":"始皇二十八年","anchor":"上問博士曰：「湘君何神？」博士對曰：「聞之，堯女，舜之妻，而葬此。」","notes":[{"source":"索隱","text":"《列女傳》亦以湘君爲堯女。按：楚詞九歌有湘君、湘夫人。夫人是堯女，則湘君當是舜。今此文以湘君爲堯女，是總而言之。"}]},{"id":"a186","section":"始皇二十八年","anchor":"女，舜之妻，而葬此。」於是始皇大怒，使刑徒三千人皆伐湘山樹，赭其山。","notes":[{"source":"正義","text":"赭音者。"}]},{"id":"a187","section":"始皇二十八年","anchor":"。」於是始皇大怒，使刑徒三千人皆伐湘山樹，赭其山。上自南郡由武關歸。","notes":[{"source":"集解","text":"應劭曰：「武關，秦南關，通南陽。」文穎曰：「武關在析西百七十里弘農界。」"},{"source":"正義","text":"《括地志》云：「故武關在商州商洛縣東九十里，春秋時少習也。杜預云少習。商縣武關也。」"}]},{"id":"a188","section":"始皇二十九年","anchor":"二十九年，始皇東游。至陽武博狼沙中，","notes":[{"source":"集解","text":"《地理志》河南陽武縣有博狼沙。"},{"source":"正義","text":"狼音浪。"}]},{"id":"a189","section":"始皇二十九年","anchor":"登之罘，刻石。其辭曰：","notes":[{"source":"索隱","text":"三句爲韻，凡十二韻。"}]},{"id":"a190","section":"始皇二十九年","anchor":"維二十九年，時在中春，","notes":[{"source":"正義","text":"中音仲。古者帝王巡狩，常以中月。"}]},{"id":"a191","section":"始皇二十九年","anchor":"十九年，時在中春，陽和方起。皇帝東游，巡登之罘，臨照于海。從臣嘉觀，","notes":[{"source":"正義","text":"從，才用反。觀音琯。"}]},{"id":"a192","section":"始皇二十九年","anchor":"聖作治，建定法度，顯箸綱紀。外教諸侯，光施文惠，明以義理。六國回辟，","notes":[{"source":"正義","text":"必亦反。"}]},{"id":"a193","section":"始皇二十九年","anchor":"定法度，顯箸綱紀。外教諸侯，光施文惠，明以義理。六國回辟，貪戾無厭，","notes":[{"source":"正義","text":"於廉反。"}]},{"id":"a194","section":"始皇二十九年","anchor":"戾無厭，虐殺不已。皇帝哀眾，遂發討師，奮揚武德。義誅信行，威燀旁達，","notes":[{"source":"集解","text":"徐廣曰：「燀，充善反。」"}]},{"id":"a195","section":"始皇二十九年","anchor":"振救黔首，周定四極。普施明法，經緯天下，永爲儀則。大矣哉！宇縣之中，","notes":[{"source":"集解","text":"宇，宇宙。縣，赤縣。"}]},{"id":"a196","section":"始皇二十九年","anchor":"周定四極。普施明法，經緯天下，永爲儀則。大矣哉！宇縣之中，承順聖意。","notes":[{"source":"索隱","text":"協韻音憶。"}]},{"id":"a197","section":"始皇二十九年","anchor":"滅六王。闡并天下，甾害絕息，永偃戎兵。皇帝明德，經理宇內，視聽不怠。","notes":[{"source":"索隱","text":"怠，協旗、疑韻，音銅綦反。故《國語》范蠡曰「得時不怠，時不再來」，亦以怠與臺爲韻。"}]},{"id":"a198","section":"始皇二十九年","anchor":"旋，遂之琅邪，道上黨入。","notes":[{"source":"索隱","text":"道猶從也。"}]},{"id":"a199","section":"始皇三十一年","anchor":"三十一年","notes":[{"source":"集解","text":"徐廣曰：「使黔首自實田也。」"}]},{"id":"a200","section":"始皇三十一年","anchor":"三十一年十二月，更名臘曰「嘉平」。","notes":[{"source":"集解","text":"太原真人茅盈內紀曰：「始皇三十一年九月庚子，盈曾祖父濛，乃於華山之中，乘雲駕龍，白日升天。先是其邑謠歌曰『神仙得者茅初成，駕龍上升入泰清，時下玄洲戲赤城，繼世而往在我盈，帝若學之臘嘉平』。始皇聞謠歌而問其故，父老具對此仙人之謠歌，勸帝求長生之術。於是始皇欣然，乃有尋仙之志，因改臘曰『嘉平』。」"},{"source":"索隱","text":"廣雅曰：「夏曰『清祀』，殷曰『嘉平』，周曰『大蜡』，亦曰『臘』，秦更曰『嘉平』。」蓋應歌謠之詞而改從殷號也。道書茅濛字初成，今此云「茅濛初成」者爲神仙之道，其意失也。蓋由裴氏所引不明，或後人增益「濛」字，遂令七言之詞有衍爾。"}]},{"id":"a201","section":"始皇三十一年","anchor":"一年十二月，更名臘曰「嘉平」。賜黔首里六石米，二羊。始皇爲微行咸陽，","notes":[{"source":"集解","text":"張晏曰：「若微賤之所爲，故曰微行也。」"}]},{"id":"a202","section":"始皇三十一年","anchor":"。賜黔首里六石米，二羊。始皇爲微行咸陽，與武士四人俱，夜出逢盜蘭池，","notes":[{"source":"集解","text":"《地理志》渭城縣有蘭池宮。"},{"source":"正義","text":"《括地志》云：「蘭池陂即古之蘭池，在咸陽縣界。秦記云『始皇都長安，引渭水爲池，築爲蓬、瀛，刻石爲鯨，長二百丈』。逢盜之處也。」"}]},{"id":"a203","section":"始皇三十二年","anchor":"三十二年，始皇之碣石，使燕人盧生求羨門、","notes":[{"source":"集解","text":"韋昭曰：「古仙人。」"}]},{"id":"a204","section":"始皇三十二年","anchor":"三十二年，始皇之碣石，使燕人盧生求羨門、高誓。","notes":[{"source":"正義","text":"亦古仙人。"}]},{"id":"a205","section":"始皇三十二年","anchor":"三十二年，始皇之碣石，使燕人盧生求羨門、高誓。刻碣石門。","notes":[{"source":"集解","text":"徐廣曰：「一作『盟』。」"}]},{"id":"a206","section":"始皇三十二年","anchor":"之碣石，使燕人盧生求羨門、高誓。刻碣石門。壞城郭，決通隄防。其辭曰：","notes":[{"source":"正義","text":"此一頌三句爲韻。"}]},{"id":"a207","section":"始皇三十二年","anchor":"遂興師旅，誅戮無道，爲逆滅息。武殄暴逆，文復無罪，","notes":[{"source":"集解","text":"徐廣曰：「復，一作『優』。」"},{"source":"正義","text":"復音福。言秦以武力能殄息暴逆，以文訓道令無罪失，故復除之。"}]},{"id":"a208","section":"始皇三十二年","anchor":"論功勞，賞及牛馬，恩肥土域。皇帝奮威，德并諸侯，初一泰平。墮壞城郭，","notes":[{"source":"正義","text":"墮音許規反。壞音怪。墮，毀也。壞，坼也。言始皇毀坼關東諸侯舊城郭也。夫自頹曰壞，音戶怪反。"}]},{"id":"a209","section":"始皇三十二年","anchor":"并諸侯，初一泰平。墮壞城郭，決通川防，夷去險阻。地勢既定，黎庶無繇，","notes":[{"source":"正義","text":"音遙。"}]},{"id":"a210","section":"始皇三十二年","anchor":"庶無繇，天下咸撫。男樂其疇，女修其業，事各有序。惠被諸產，久並來田，","notes":[{"source":"集解","text":"徐廣曰：「久，一作『分』。」"}]},{"id":"a211","section":"始皇三十二年","anchor":"因使韓終、侯公、石生求仙人不死之藥。始皇巡北邊，從上郡入。燕人盧生使","notes":[{"source":"正義","text":"音所吏反。"}]},{"id":"a212","section":"始皇三十二年","anchor":"從上郡入。燕人盧生使入海還，以鬼神事，因奏錄圖書，曰「亡秦者胡也」。","notes":[{"source":"集解","text":"鄭玄曰：「胡，胡亥，秦二世名也。秦見圖書，不知此爲人名，反備北胡。」"}]},{"id":"a213","section":"始皇三十二年","anchor":"，曰「亡秦者胡也」。始皇乃使將軍蒙恬發兵三十萬人北擊胡，略取河南地。","notes":[{"source":"正義","text":"今靈、夏、勝等州，秦略取之。"}]},{"id":"a214","section":"始皇三十三年","anchor":"三十三年，發諸嘗逋亡人、贅壻、","notes":[{"source":"集解","text":"瓚曰：「贅，謂居窮有子，使就其婦家爲贅壻。」"}]},{"id":"a215","section":"始皇三十三年","anchor":"三十三年，發諸嘗逋亡人、贅壻、賈人略取陸梁地，","notes":[{"source":"索隱","text":"謂南方之人，其性陸梁，故曰陸梁。"},{"source":"正義","text":"嶺南人多處山陸，其性強梁，故曰陸梁。"}]},{"id":"a216","section":"始皇三十三年","anchor":"三十三年，發諸嘗逋亡人、贅壻、賈人略取陸梁地，爲桂林、","notes":[{"source":"集解","text":"韋昭曰：「今鬱林是也。」"}]},{"id":"a217","section":"始皇三十三年","anchor":"三十三年，發諸嘗逋亡人、贅壻、賈人略取陸梁地，爲桂林、象郡、","notes":[{"source":"集解","text":"韋昭曰：「今日南。」"}]},{"id":"a218","section":"始皇三十三年","anchor":"三十三年，發諸嘗逋亡人、贅壻、賈人略取陸梁地，爲桂林、象郡、南海，","notes":[{"source":"正義","text":"即廣州南海縣。"}]},{"id":"a219","section":"始皇三十三年","anchor":"，發諸嘗逋亡人、贅壻、賈人略取陸梁地，爲桂林、象郡、南海，以適遣戍。","notes":[{"source":"集解","text":"徐廣曰：「五十萬人守五嶺。」"},{"source":"正義","text":"適音直革反。戍，守也。廣州記云：「五嶺者，大庾、始安、臨賀、揭楊、桂陽。」《輿地志》云：「一曰臺嶺，亦名塞上，今名大庾；二曰騎田；三曰都龐；四曰萌諸；五曰越嶺。」"}]},{"id":"a220","section":"始皇三十三年","anchor":"、賈人略取陸梁地，爲桂林、象郡、南海，以適遣戍。西北斥逐匈奴。自榆中","notes":[{"source":"集解","text":"徐廣曰：「在金城。」"}]},{"id":"a221","section":"始皇三十三年","anchor":"陸梁地，爲桂林、象郡、南海，以適遣戍。西北斥逐匈奴。自榆中並河以東，","notes":[{"source":"集解","text":"服虔曰：「並音傍。傍，依也。」"}]},{"id":"a222","section":"始皇三十三年","anchor":"桂林、象郡、南海，以適遣戍。西北斥逐匈奴。自榆中並河以東，屬之陰山，","notes":[{"source":"集解","text":"徐廣曰：「在五原北。」"},{"source":"正義","text":"屬，之欲反。按：五原，今勝州也。"}]},{"id":"a223","section":"始皇三十三年","anchor":"，屬之陰山，以爲（三）〔四〕十四縣，城河上爲塞。又使蒙恬渡河取高闕、","notes":[{"source":"正義","text":"高闕，山名，在五原北。兩山相對若闕，甚高，故言高闕。"}]},{"id":"a224","section":"始皇三十三年","anchor":"四〕十四縣，城河上爲塞。又使蒙恬渡河取高闕、（陶）〔陽〕山、北假中，","notes":[{"source":"集解","text":"晉灼曰：「王莽傳云『五原北假，膏壤殖穀』。北假，地名也。」"},{"source":"索隱","text":"高闕，山名；北假，地名。近五原。"},{"source":"正義","text":"酈元《注水經》云：「黃河逕河目縣故城西，縣在北假中。」北假，地名也。按：河目縣屬勝州，今名河北。《漢書地理志》云屬五原郡。"}]},{"id":"a225","section":"始皇三十三年","anchor":"渡河取高闕、（陶）〔陽〕山、北假中，築亭障以逐戎人。徙謫，實之初縣。","notes":[{"source":"索隱","text":"徙有罪而謫之，以實初縣，即上「自榆中屬陰山，以爲三十四縣」是也。故漢七科謫亦因於秦。"}]},{"id":"a226","section":"始皇三十三年","anchor":"〕山、北假中，築亭障以逐戎人。徙謫，實之初縣。禁不得祠。明星出西方。","notes":[{"source":"集解","text":"徐廣曰：「皇甫謐云彗星見。」"}]},{"id":"a227","section":"始皇三十四年","anchor":"三十四年，適治獄吏不直者，築長城及南越地。","notes":[{"source":"正義","text":"謂戍五嶺，是南方越地。"}]},{"id":"a228","section":"始皇三十四年","anchor":"始皇置酒咸陽宮，博士七十人前爲壽。僕射","notes":[{"source":"集解","text":"《漢書百官表》曰：「僕射，秦官。古者重武，官有主射以督課之。」應劭曰：「僕，主也。」"},{"source":"正義","text":"射音夜。"}]},{"id":"a229","section":"始皇三十四年","anchor":"，自爲枝輔。今陛下有海內，而子弟爲匹夫，卒有田常、六卿之臣，無輔拂，","notes":[{"source":"正義","text":"蒲筆反。"}]},{"id":"a230","section":"始皇三十四年","anchor":"厚招游學。今天下已定，法令出一，百姓當家則力農工，士則學習法令辟禁。","notes":[{"source":"正義","text":"令，力性反。辟音避。"}]},{"id":"a231","section":"始皇三十四年","anchor":"莫之能一，是以諸侯並作，語皆道古以害今，飾虛言以亂實，人善其所私學，","notes":[{"source":"集解","text":"徐廣曰：「私，一作『知』。」"}]},{"id":"a232","section":"始皇三十四年","anchor":"與非法教，人聞令下，則各以其學議之，入則心非，出則巷議，夸主以爲名，","notes":[{"source":"正義","text":"夸，口瓜反。"}]},{"id":"a233","section":"始皇三十四年","anchor":"，天下敢有藏詩、書、百家語者，悉詣守、尉雜燒之。有敢偶語詩書者弃市。","notes":[{"source":"集解","text":"應劭曰：「禁民聚語，畏其謗己。」"},{"source":"正義","text":"偶，對也。"}]},{"id":"a234","section":"始皇三十四年","anchor":"者弃市。以古非今者族。吏見知不舉者與同罪。令下三十日不燒，黥爲城旦。","notes":[{"source":"集解","text":"如淳曰：「律說『論決爲髡鉗，輸邊築長城，晝日伺寇虜，夜暮築長城』。城旦，四歲刑。」"}]},{"id":"a235","section":"始皇三十四年","anchor":"令下三十日不燒，黥爲城旦。所不去者，醫藥卜筮種樹之書。若欲有學法令，","notes":[{"source":"集解","text":"徐廣曰：「一無『法令』二字。」"}]},{"id":"a236","section":"始皇三十五年","anchor":"三十五年，除道，道九原","notes":[{"source":"集解","text":"《地理志》五原郡有九原縣。"}]},{"id":"a237","section":"始皇三十五年","anchor":"三十五年，除道，道九原抵雲陽，","notes":[{"source":"集解","text":"徐廣曰：「表云道九原，通甘泉。」"}]},{"id":"a238","section":"始皇三十五年","anchor":"王都鎬，豐鎬之閒，帝王之都也。乃營作朝宮渭南上林苑中。先作前殿阿房，","notes":[{"source":"正義","text":"房，白郎反。《括地志》云：「秦阿房宮亦曰阿城，在雍州長安縣西北一十四里。」按：宮在上林苑中，雍州郭城西南面，即阿房宮城東面也。顏師古云「阿，近也。以其去咸陽近，且號阿房」。"}]},{"id":"a239","section":"始皇三十五年","anchor":"先作前殿阿房，東西五百步，南北五十丈，上可以坐萬人，下可以建五丈旗。","notes":[{"source":"索隱","text":"此以其形名宮也，言其宮四阿旁廣也，故云下可建五丈之旗也。阿房，後爲宮名。"},{"source":"正義","text":"三輔舊事云：「阿房宮東西三里，南北五百步，庭中可受萬人。又鑄銅人十二於宮前。阿房宮以慈石爲門，阿房宮之北闕門也。」"}]},{"id":"a240","section":"始皇三十五年","anchor":"之顛以爲闕。爲復道，自阿房渡渭，屬之咸陽，以象天極閣道絕漢抵營室也。","notes":[{"source":"索隱","text":"謂爲複道，渡渭屬咸陽，象天文閣道絕漢抵營室也。常考《天官書》曰「天極紫宮後十七星絕漢抵營室，曰閣道」。"}]},{"id":"a241","section":"始皇三十五年","anchor":"也。阿房宮未成；成，欲更擇令名名之。作宮阿房，故天下謂之阿房宮。隱宮","notes":[{"source":"正義","text":"餘刑見於市朝。宮刑，一百日隱於蔭室養之乃可，故曰隱宮，下蠶室是。"}]},{"id":"a242","section":"始皇三十五年","anchor":"三百，關外四百餘。於是立石東海上朐界中，以爲秦東門。因徙三萬家麗邑，","notes":[{"source":"正義","text":"麗音離。"}]},{"id":"a243","section":"始皇三十五年","anchor":"，真人至。人主所居而人臣知之，則害於神。真人者，入水不濡，入火不爇，","notes":[{"source":"正義","text":"而說反。"}]},{"id":"a244","section":"始皇三十五年","anchor":"鼓美人充之，各案署不移徙。行所幸，有言其處者，罪死。始皇帝幸梁山宮，","notes":[{"source":"集解","text":"徐廣曰：「在好畤。」"},{"source":"正義","text":"《括地志》云：「俗名望宮山，在雍州好畤縣西十二里，北去梁山九里。秦始皇（起）〔紀〕『從山上見丞相車騎眾，弗善』，即此山也。」"}]},{"id":"a245","section":"始皇三十五年","anchor":"侯生、","notes":[{"source":"集解","text":"說苑曰：「韓客侯生也。」"}]},{"id":"a246","section":"始皇三十五年","anchor":"雖七十人，特備員弗用。丞相諸大臣皆受成事，倚辨於上。上樂以刑殺爲威，","notes":[{"source":"正義","text":"樂，五孝反。"}]},{"id":"a247","section":"始皇三十五年","anchor":"畏罪持祿，莫敢盡忠。上不聞過而日驕，下懾伏謾欺以取容。秦法，不得兼方","notes":[{"source":"集解","text":"徐廣曰：「一云『并力』。」"},{"source":"正義","text":"言秦施法不得兼方者，令民之有方伎不得兼兩齊，試不驗，輒賜死。言法酷。"}]},{"id":"a248","section":"始皇三十五年","anchor":"士，畏忌諱諛，不敢端言其過。天下之事無小大皆決於上，上至以衡石量書，","notes":[{"source":"集解","text":"石百二十斤。"},{"source":"正義","text":"衡，秤衡也。言表牋奏請，秤取一石，日夜有程期，不滿不休息。"}]},{"id":"a249","section":"始皇三十五年","anchor":"敢端言其過。天下之事無小大皆決於上，上至以衡石量書，日夜有呈，不中呈","notes":[{"source":"正義","text":"中，竹仲反。"}]},{"id":"a250","section":"始皇三十五年","anchor":"書不中用者盡去之。悉召文學方術士甚眾，欲以興太平，方士欲練以求奇藥。","notes":[{"source":"集解","text":"徐廣曰：「一云『欲以練求』。」"}]},{"id":"a251","section":"始皇三十五年","anchor":"者盡去之。悉召文學方術士甚眾，欲以興太平，方士欲練以求奇藥。今聞韓眾","notes":[{"source":"正義","text":"音終。"}]},{"id":"a252","section":"始皇三十五年","anchor":"求奇藥。今聞韓眾去不報，徐巿等費以巨萬計，終不得藥，徒姦利相告日聞。","notes":[{"source":"集解","text":"徐廣曰：「一作『閒』。」"}]},{"id":"a253","section":"始皇三十五年","anchor":"自除犯禁者四百六十餘人，皆阬之咸陽，使天下知之，以懲後。益發謫徙邊。","notes":[{"source":"集解","text":"徐廣曰：「表云徙於北河、榆中，耐徙三處。拜爵一級。」"}]},{"id":"a254","section":"始皇三十五年","anchor":"皆重法繩之，臣恐天下不安。唯上察之。」始皇怒，使扶蘇北監蒙恬於上郡。","notes":[{"source":"正義","text":"《括地志》云：「上郡故城在綏州上縣東南五十里，秦之上郡城也。」"}]},{"id":"a255","section":"始皇三十六年","anchor":"三十六年，熒惑守心。有墜星下東郡，至地爲石，","notes":[{"source":"集解","text":"徐廣曰：「表云石晝隕。」"}]},{"id":"a256","section":"始皇三十六年","anchor":"居人誅之，因燔銷其石。始皇不樂，使博士爲仙真人詩，及行所游天下，傳令","notes":[{"source":"正義","text":"傳，逐戀反。令，力呈反。"}]},{"id":"a257","section":"始皇三十六年","anchor":"真人詩，及行所游天下，傳令樂人謌弦之。秋，使者從關東夜過華陰平舒道，","notes":[{"source":"正義","text":"《括地志》云：「平舒故城在華州華陰縣西北六里。水經注云『渭水又東經平舒北，城枕渭濱，半破淪水，南面通衢。昔秦之將亡也，江神送璧於華陰平舒道，即其處也』。」"}]},{"id":"a258","section":"始皇三十六年","anchor":"。秋，使者從關東夜過華陰平舒道，有人持璧遮使者曰：「爲吾遺滈池君。」","notes":[{"source":"集解","text":"服虔曰：「水神也。」張晏曰：「武王居鎬，鎬池君則武王也。武王伐商，故神云始皇荒淫若紂矣，今亦可伐也。」孟康曰：「長安西南有滈池。」"},{"source":"索隱","text":"按：服虔云水神，是也。江神以璧遺滈池之神，告始皇之將終也。且秦水德王，故其君將亡，水神先自相告也。"},{"source":"正義","text":"遺，庾季反。滈，湖老反。《括地志》云：「滈水源出雍州長安縣西北滈池。酈元《注水經》云『滈水承滈池，北流入渭』。今按：滈池水流入來通渠，蓋酈元誤矣。」張晏云：「武王居滈，滈池君則武王也。伐商，故神云始皇荒淫若紂矣，今武王可伐矣。」"}]},{"id":"a259","section":"始皇三十六年","anchor":"平舒道，有人持璧遮使者曰：「爲吾遺滈池君。」因言曰：「今年祖龍死。」","notes":[{"source":"集解","text":"蘇林曰：「祖，始也。龍，人君象。謂始皇也。」服虔曰：「龍，人之先象也，言王亦人之先也。」應劭曰：「祖，人之先。龍，君之象。」"}]},{"id":"a260","section":"始皇三十六年","anchor":"二十八年行渡江所沈璧也。於是始皇卜之，卦得游徙吉。遷北河榆中三萬家。","notes":[{"source":"正義","text":"謂北河勝州也。榆中即今勝州榆林縣也。言徙三萬家以應卜卦游徙吉也。"}]},{"id":"a261","section":"始皇三十七年","anchor":"疾守。少子胡亥愛慕請從，上許之。十一月，行至雲夢，望祀虞舜於九疑山。","notes":[{"source":"正義","text":"《括地志》云：「九疑山在永州唐興縣東南一百里。《皇覽冢墓記》云舜冢在零陵郡營浦縣九疑山。」言始皇至雲夢，望祭虞舜於九疑山也。"}]},{"id":"a262","section":"始皇三十七年","anchor":"上許之。十一月，行至雲夢，望祀虞舜於九疑山。浮江下，觀籍柯，渡海渚。","notes":[{"source":"正義","text":"《括地志》云：「舒州同安縣東。」按：舒州在江中，疑「海」字誤，即此州也。"}]},{"id":"a263","section":"始皇三十七年","anchor":"十一月，行至雲夢，望祀虞舜於九疑山。浮江下，觀籍柯，渡海渚。過丹陽，","notes":[{"source":"正義","text":"《括地志》云：「丹陽郡故在潤州江寧縣東南五里，秦兼并天下，以爲鄣郡也。」"}]},{"id":"a264","section":"始皇三十七年","anchor":"行至雲夢，望祀虞舜於九疑山。浮江下，觀籍柯，渡海渚。過丹陽，至錢唐。","notes":[{"source":"正義","text":"錢唐，今杭州縣。"}]},{"id":"a265","section":"始皇三十七年","anchor":"，望祀虞舜於九疑山。浮江下，觀籍柯，渡海渚。過丹陽，至錢唐。臨浙江，","notes":[{"source":"集解","text":"晉灼曰：「其流東至會稽山陰而西折，故稱浙。音折。」"}]},{"id":"a266","section":"始皇三十七年","anchor":"籍柯，渡海渚。過丹陽，至錢唐。臨浙江，水波惡，乃西百二十里從狹中渡。","notes":[{"source":"集解","text":"徐廣曰：「蓋在餘杭也。顧夷曰『餘杭者，秦始皇至會稽經此，立爲縣』。」"}]},{"id":"a267","section":"始皇三十七年","anchor":"丹陽，至錢唐。臨浙江，水波惡，乃西百二十里從狹中渡。上會稽，祭大禹，","notes":[{"source":"正義","text":"上音上掌反。越州會稽山上有夏禹穴及廟。"}]},{"id":"a268","section":"始皇三十七年","anchor":"江，水波惡，乃西百二十里從狹中渡。上會稽，祭大禹，望于南海，而立石刻","notes":[{"source":"索隱","text":"望于南海而刻石。三句爲韻，凡二十四韻。"}]},{"id":"a269","section":"始皇三十七年","anchor":"百二十里從狹中渡。上會稽，祭大禹，望于南海，而立石刻頌秦德。其文曰：","notes":[{"source":"正義","text":"此二頌三句爲韻。其碑見在會稽山上。其文及書皆李斯，其字四寸，畫如小指，圓鐫。今文字整頓，是小篆字。"}]},{"id":"a270","section":"始皇三十七年","anchor":"皇帝休烈，平一宇內，德惠脩長。","notes":[{"source":"索隱","text":"脩亦長也，重文耳。王劭按張徽所錄會稽南山秦始皇碑文，「脩」作「攸」。"}]},{"id":"a271","section":"始皇三十七年","anchor":"覽遠方。遂登會稽，宣省習俗，黔首齋莊。羣臣誦功，本原事迹，追首高明。","notes":[{"source":"索隱","text":"今檢會稽刻石文「首」字作「道」，雅符人情也。"}]},{"id":"a272","section":"始皇三十七年","anchor":"首齋莊。羣臣誦功，本原事迹，追首高明。秦聖臨國，始定刑名，顯陳舊章。","notes":[{"source":"正義","text":"作「彰」，音章。碑文作「畫璋」也。"}]},{"id":"a273","section":"始皇三十七年","anchor":"陳舊章。初平法式，審別職任，以立恆常。六王專倍，貪戾慠猛，率眾自彊。","notes":[{"source":"正義","text":"碑文作「率眾邦強」。"}]},{"id":"a274","section":"始皇三十七年","anchor":"平法式，審別職任，以立恆常。六王專倍，貪戾慠猛，率眾自彊。暴虐恣行，","notes":[{"source":"正義","text":"寒彭反。"}]},{"id":"a275","section":"始皇三十七年","anchor":"立恆常。六王專倍，貪戾慠猛，率眾自彊。暴虐恣行，負力而驕，數動甲兵。","notes":[{"source":"正義","text":"數音朔。"}]},{"id":"a276","section":"始皇三十七年","anchor":"王專倍，貪戾慠猛，率眾自彊。暴虐恣行，負力而驕，數動甲兵。陰通閒使，","notes":[{"source":"正義","text":"閒，紀莧反，又如字。使，所吏反。"}]},{"id":"a277","section":"始皇三十七年","anchor":"戾慠猛，率眾自彊。暴虐恣行，負力而驕，數動甲兵。陰通閒使，以事合從，","notes":[{"source":"正義","text":"合音閤。從，子容反。"}]},{"id":"a278","section":"始皇三十七年","anchor":"眾自彊。暴虐恣行，負力而驕，數動甲兵。陰通閒使，以事合從，行爲辟方。","notes":[{"source":"正義","text":"行，下孟反。辟，匹亦反。"}]},{"id":"a279","section":"始皇三十七年","anchor":"虐恣行，負力而驕，數動甲兵。陰通閒使，以事合從，行爲辟方。內飾詐謀，","notes":[{"source":"索隱","text":"刻石文作「謀詐」。"}]},{"id":"a280","section":"始皇三十七年","anchor":"使，以事合從，行爲辟方。內飾詐謀，外來侵邊，遂起禍殃。義威誅之，殄熄","notes":[{"source":"集解","text":"徐廣曰：「音息。」"}]},{"id":"a281","section":"始皇三十七年","anchor":"事合從，行爲辟方。內飾詐謀，外來侵邊，遂起禍殃。義威誅之，殄熄暴悖，","notes":[{"source":"正義","text":"殄，田典反。暴，白報反。悖音背。"}]},{"id":"a282","section":"始皇三十七年","anchor":"理羣物，考驗事實，各載其名。貴賤並通，善否陳前，靡有隱情。飾省宣義，","notes":[{"source":"集解","text":"徐廣曰：「省，一作『非』。」"},{"source":"正義","text":"飾音式。省，山景反。飾謂文飾也。省，過也。"}]},{"id":"a283","section":"始皇三十七年","anchor":"驗事實，各載其名。貴賤並通，善否陳前，靡有隱情。飾省宣義，有子而嫁，","notes":[{"source":"正義","text":"謂夫死有子，棄之而嫁。"}]},{"id":"a284","section":"始皇三十七年","anchor":"省宣義，有子而嫁，倍死不貞。防隔內外，禁止淫泆，男女絜誠。夫爲寄豭，","notes":[{"source":"索隱","text":"豭，牡豬也。言夫淫他室，若寄豭之豬也。豭音加。"}]},{"id":"a285","section":"始皇三十七年","anchor":"隔內外，禁止淫泆，男女絜誠。夫爲寄豭，殺之無罪，男秉義程。妻爲逃嫁，","notes":[{"source":"正義","text":"謂棄夫而逃嫁於人。"}]},{"id":"a286","section":"始皇三十七年","anchor":"止淫泆，男女絜誠。夫爲寄豭，殺之無罪，男秉義程。妻爲逃嫁，子不得母，","notes":[{"source":"正義","text":"言妻棄夫逃嫁，子乃失母。"}]},{"id":"a287","section":"始皇三十七年","anchor":"化廉清。大治濯俗，天下承風，蒙被休經。皆遵度軌，和安敦勉，莫不順令。","notes":[{"source":"正義","text":"力呈反。"}]},{"id":"a288","section":"始皇三十七年","anchor":"下承風，蒙被休經。皆遵度軌，和安敦勉，莫不順令。黔首脩絜，人樂同則，","notes":[{"source":"正義","text":"樂音岳。"}]},{"id":"a289","section":"始皇三十七年","anchor":"首脩絜，人樂同則，嘉保太平。後敬奉法，常治無極，輿舟不傾。從臣誦烈，","notes":[{"source":"正義","text":"從音才用反。烈，美也。所隨巡從諸臣，咸誦美，請刻此石。"}]},{"id":"a290","section":"始皇三十七年","anchor":"還過吳，從江乘渡。","notes":[{"source":"集解","text":"《地理志》丹陽有江乘縣。"},{"source":"索隱","text":"《地理志》丹陽有江乘縣。"},{"source":"正義","text":"乘音時升反。江乘故縣在潤州句容縣北六十里，本秦舊縣也。渡謂濟渡也。"}]},{"id":"a291","section":"始皇三十七年","anchor":"神藥，數歲不得，費多，恐譴，乃詐曰：「蓬萊藥可得，然常爲大鮫魚所苦，","notes":[{"source":"正義","text":"鮫音交。苦音苦故反。"}]},{"id":"a292","section":"始皇三十七年","anchor":"。」乃令入海者齎捕巨魚具，而自以連弩候大魚出射之。自琅邪北至榮成山，","notes":[{"source":"正義","text":"即成山也，在萊州。"}]},{"id":"a293","section":"始皇三十七年","anchor":"至平原津而病。","notes":[{"source":"集解","text":"徐廣曰：「渡河而西。」"},{"source":"正義","text":"今德州平原縣南六十里有張公故城，城東有水津焉，後名張公渡，恐此平原郡古津也。《漢書》公孫弘平津侯，亦近此。蓋平津即此津，始皇渡此津而疾。"}]},{"id":"a294","section":"始皇三十七年","anchor":"甚，乃爲璽書賜公子扶蘇曰：「與喪會咸陽而葬。」書已封，在中車府令趙高","notes":[{"source":"集解","text":"伏儼曰：「主乘輿路車。」"}]},{"id":"a295","section":"始皇三十七年","anchor":"封，在中車府令趙高行符璽事所，未授使者。七月丙寅，始皇崩於沙丘平臺。","notes":[{"source":"集解","text":"徐廣曰：「年五十。沙丘去長安二千餘里。趙有沙丘宮，在鉅鹿，武靈王之死處。」"},{"source":"正義","text":"《括地志》云：「沙丘臺在邢州平鄉縣東北二十里。又云平鄉縣東北四十里。」按：始皇崩在沙丘之宮，平臺之中。邢州去京一千六百五十里。"}]},{"id":"a296","section":"始皇三十七年","anchor":"行符璽事所，未授使者。七月丙寅，始皇崩於沙丘平臺。丞相斯爲上崩在外，","notes":[{"source":"正義","text":"爲，于僞反。"}]},{"id":"a297","section":"始皇三十七年","anchor":"丞相斯爲上崩在外，恐諸公子及天下有變，乃祕之，不發喪。棺載轀涼車中，","notes":[{"source":"正義","text":"棺音館。又古患反。"}]},{"id":"a298","section":"始皇三十七年","anchor":"書及獄律令法事，胡亥私幸之。高乃與公子胡亥、丞相斯陰謀破去始皇所封書","notes":[{"source":"正義","text":"去，丘呂反。"}]},{"id":"a299","section":"始皇三十七年","anchor":"相斯受始皇遺詔沙丘，立子胡亥爲太子。更爲書賜公子扶蘇、蒙恬，數以罪，","notes":[{"source":"正義","text":"數音色具反。"}]},{"id":"a300","section":"始皇三十七年","anchor":"書賜公子扶蘇、蒙恬，數以罪，（其）賜死。語具在李斯傳中。行，遂從井陘","notes":[{"source":"集解","text":"徐廣曰：「在常山。」"}]},{"id":"a301","section":"始皇三十七年","anchor":"扶蘇、蒙恬，數以罪，（其）賜死。語具在李斯傳中。行，遂從井陘抵九原。","notes":[{"source":"正義","text":"抵，丁禮反。抵，至也。從沙丘至勝州三千里。"}]},{"id":"a302","section":"始皇三十七年","anchor":"斯傳中。行，遂從井陘抵九原。會暑，上轀車臭，乃詔從官令車載一石鮑魚，","notes":[{"source":"正義","text":"鮑，白卯反。"}]},{"id":"a303","section":"始皇三十七年","anchor":"。始皇初即位，穿治酈山，及并天下，天下徒送詣七十餘萬人，穿三泉，下銅","notes":[{"source":"集解","text":"徐廣曰：「一作『錮』。錮，鑄塞。」"},{"source":"正義","text":"顏師古云：「三重之泉，言至水也。」"}]},{"id":"a304","section":"始皇三十七年","anchor":"天下徒送詣七十餘萬人，穿三泉，下銅而致椁，宮觀百官奇器珍怪徙臧滿之。","notes":[{"source":"正義","text":"言冢內作宮觀及百官位次，奇器珍怪徙滿冢中。臧，才浪反。"}]},{"id":"a305","section":"始皇三十七年","anchor":"之。令匠作機弩矢，有所穿近者輒射之。以水銀爲百川江河大海，機相灌輸，","notes":[{"source":"正義","text":"灌音館。輸音戍。"}]},{"id":"a306","section":"始皇三十七年","anchor":"。以水銀爲百川江河大海，機相灌輸，上具天文，下具地理。以人魚膏爲燭，","notes":[{"source":"集解","text":"徐廣曰：「人魚似鮎，四腳。」"},{"source":"正義","text":"廣志云：「鯢魚聲如小兒啼，有四足，形如鱧，可以治牛，出伊水。」異物志云：「人魚似人形，長尺餘。不堪食。皮利於鮫魚，鋸材木入。項上有小穿，氣從中出。秦始皇冢中以人魚膏爲燭，即此魚也。出東海中，今台州有之。」按：今帝王用漆燈冢中，則火不滅。"}]},{"id":"a307","section":"始皇三十七年","anchor":"江河大海，機相灌輸，上具天文，下具地理。以人魚膏爲燭，度不滅者久之。","notes":[{"source":"正義","text":"度音田洛反。"}]},{"id":"a308","section":"始皇三十七年","anchor":"。葬既已下，或言工匠爲機，臧皆知之，臧重即泄。大事畢，已臧，閉中羨，","notes":[{"source":"正義","text":"音延，下同。謂冢中神道。"}]},{"id":"a309","section":"始皇三十七年","anchor":"事畢，已臧，閉中羨，下外羨門，盡閉工匠臧者，無復出者。樹草木以象山。","notes":[{"source":"集解","text":"《皇覽》曰：「墳高五十餘丈，周迴五里餘。」"},{"source":"正義","text":"《關中記》云：「始皇陵在驪山。泉本北流，障使東西流。有土無石，取大石於渭（山）〔南〕諸山。」《括地志》云：「秦始皇陵在雍州新豐縣西南十里。」"}]},{"id":"a310","section":"二世元年","anchor":"二世皇帝元年，年二十一。","notes":[{"source":"集解","text":"徐廣曰：「表云十月戊寅，大赦罪人。」"}]},{"id":"a311","section":"二世元年","anchor":"二世皇帝元年，年二十一。趙高爲郎中令，","notes":[{"source":"集解","text":"《漢書百官表》曰：「秦官，掌宮殿門戶。」"}]},{"id":"a312","section":"二世元年","anchor":"廟。羣臣皆頓首言曰：「古者天子七廟，諸侯五，大夫三，雖萬世世不軼毀。","notes":[{"source":"正義","text":"軼，徒結反。"}]},{"id":"a313","section":"二世元年","anchor":"皇爲極廟，四海之內皆獻貢職，增犧牲，禮咸備，毋以加。先王廟或在西雍，","notes":[{"source":"正義","text":"於用反。西雍在咸陽西，今岐州雍縣故城是也。又一云西雍，雍西縣也。"}]},{"id":"a314","section":"二世元年","anchor":"東行郡縣，李斯從。到碣石，並海，南至會稽，而盡刻始皇所立刻石，石旁著","notes":[{"source":"正義","text":"丁略反。"}]},{"id":"a315","section":"二世元年","anchor":"皇帝曰：「金石刻盡始皇帝所爲也。今襲號而金石刻辭不稱","notes":[{"source":"正義","text":"尺證反。"}]},{"id":"a316","section":"二世元年","anchor":"帝曰：「金石刻盡始皇帝所爲也。今襲號而金石刻辭不稱始皇帝，其於久遠也","notes":[{"source":"正義","text":"二世言始滅六國，威振古今，自五帝三王未及，既已襲位，而見金石盡刻其頌，不稱始皇成功盛德甚遠矣。"}]},{"id":"a317","section":"二世元年","anchor":"稱始皇帝，其於久遠也如後嗣爲之者，不稱成功盛德。」丞相臣斯、臣去疾、","notes":[{"source":"集解","text":"徐廣曰：「姓馮。」"},{"source":"正義","text":"去，丘呂反。"}]},{"id":"a318","section":"二世元年","anchor":"國安矣。」二世曰：「善。」乃行誅大臣及諸公子，以罪過連逮少近官三郎，","notes":[{"source":"索隱","text":"逮訓及也。謂連及俱被捕，故云連逮。少，小也。近，近侍之臣。三郎謂中郎、外郎、散郎。"},{"source":"正義","text":"《漢書百官表》云有議郎、中郎、散郎，又有左右三將，謂郎中、車郎、戶郎。"}]},{"id":"a319","section":"二世元年","anchor":"：「先帝爲咸陽朝廷小，故營阿房宮爲室堂。未就，會上崩，罷其作者，復土","notes":[{"source":"正義","text":"謂出土爲陵，既成，還復其土，故言復土。"}]},{"id":"a320","section":"二世元年","anchor":"就，則是章先帝舉事過也。」復作阿房宮。外撫四夷，如始皇計。盡徵其材士","notes":[{"source":"正義","text":"謂材官蹶張之士。"}]},{"id":"a321","section":"二世元年","anchor":"夷，如始皇計。盡徵其材士五萬人爲屯衞咸陽，令教射狗馬禽獸。當食者多，","notes":[{"source":"正義","text":"謂材士及狗馬。"}]},{"id":"a322","section":"二世元年","anchor":"。盡徵其材士五萬人爲屯衞咸陽，令教射狗馬禽獸。當食者多，度不足，下調","notes":[{"source":"正義","text":"度，田洛反。下，行嫁反。調，田弔反。謂下令調斂也。"}]},{"id":"a323","section":"二世元年","anchor":"七月，戍卒陳勝","notes":[{"source":"正義","text":"音升。"}]},{"id":"a324","section":"二世元年","anchor":"七月，戍卒陳勝等反故荊地，爲「張楚」。","notes":[{"source":"集解","text":"李奇曰：「張大楚國也。」"}]},{"id":"a325","section":"二世元年","anchor":"尉令丞反，以應陳涉，相立爲侯王，合從西鄉，名爲伐秦，不可勝數也。謁者","notes":[{"source":"集解","text":"《漢書百官表》曰：「謁者，秦官，掌賓贊受事。」"}]},{"id":"a326","section":"二世元年","anchor":"守尉方逐捕，今盡得，不足憂。」上悅。武臣自立爲趙王，魏咎爲魏王，田儋","notes":[{"source":"集解","text":"服虔曰：「音負擔。」"}]},{"id":"a327","section":"二世二年","anchor":"二年冬，陳涉所遣周章等將西至戲，","notes":[{"source":"集解","text":"應劭曰：「戲，弘農湖西界也。」孟康曰：「水名，今戲亭是也。」蘇林曰：「邑名，在新豐東南三十里。」"},{"source":"正義","text":"戲音許宜反。《括地志》云：「戲水源出雍州新豐縣西南驪山。水經注云戲水出驪山馮公谷，東北流。今新豐縣東北十一里戲水當官道，即其處。」"}]},{"id":"a328","section":"二世二年","anchor":"章等將西至戲，兵數十萬。二世大驚，與羣臣謀曰：「柰何？」少府章邯曰：","notes":[{"source":"集解","text":"《漢書百官表》曰：「少府，秦官。」應劭曰：「掌山澤陂池之稅，名曰禁錢，以給私養，自別爲藏。少者小也，故稱少府。」"},{"source":"正義","text":"邯，胡甘反。"}]},{"id":"a329","section":"二世二年","anchor":"授兵以擊之。」二世乃大赦天下，使章邯將，擊破周章軍而走，遂殺章曹陽。","notes":[{"source":"集解","text":"晉灼曰：「亭名，在弘農東十三里。魏武帝改曰好陽。」"},{"source":"正義","text":"《括地志》云：「曹陽故亭一名好陽亭，在陝州桃林縣東南十四里，即章邯殺周文處。」"}]},{"id":"a330","section":"二世二年","anchor":"軍而走，遂殺章曹陽。二世益遣長史司馬欣、董翳佐章邯擊盜，殺陳勝城父，","notes":[{"source":"正義","text":"父音甫。《括地志》云：「城父，亳州所理縣。」"}]},{"id":"a331","section":"二世二年","anchor":"章曹陽。二世益遣長史司馬欣、董翳佐章邯擊盜，殺陳勝城父，破項梁定陶，","notes":[{"source":"正義","text":"今曹州定陶縣。"}]},{"id":"a332","section":"二世二年","anchor":"益遣長史司馬欣、董翳佐章邯擊盜，殺陳勝城父，破項梁定陶，滅魏咎臨濟。","notes":[{"source":"正義","text":"今齊州縣。"}]},{"id":"a333","section":"二世二年","anchor":"梁定陶，滅魏咎臨濟。楚地盜名將已死，章邯乃北渡河，擊趙王歇等於鉅鹿。","notes":[{"source":"正義","text":"《括地志》云：「邢州平鄉縣城，本鉅鹿，〔王〕離圍趙王歇即此城。」"}]},{"id":"a334","section":"二世二年","anchor":"即位，柰何與公卿廷決事？事即有誤，示羣臣短也。天子稱朕，固不聞聲。」","notes":[{"source":"索隱","text":"一作「固聞聲」。言天子常處禁中，臣下屬望，纔有兆朕，聞其聲耳，不見其形也。"}]},{"id":"a335","section":"二世二年","anchor":"決事？事即有誤，示羣臣短也。天子稱朕，固不聞聲。」於是二世常居禁中，","notes":[{"source":"集解","text":"蔡邕曰：「禁中者，門戶有禁，非侍御者不得入，故曰禁中。」"}]},{"id":"a336","section":"二世二年","anchor":"，然猶不止。盜多，皆以戍漕轉作事苦，賦稅大也。請且止阿房宮作者，減省","notes":[{"source":"正義","text":"上色反。"}]},{"id":"a337","section":"二世二年","anchor":"阿房宮作者，減省四邊戍轉。」二世曰：「吾聞之韓子曰：『堯舜采椽不刮，","notes":[{"source":"索隱","text":"采，木名。刮音括。"}]},{"id":"a338","section":"二世二年","anchor":"邊戍轉。」二世曰：「吾聞之韓子曰：『堯舜采椽不刮，茅茨不翦，飯土塯，","notes":[{"source":"集解","text":"徐廣曰：「呂靜云飯器謂之簋。」"},{"source":"索隱","text":"如字，一音鏤。一作「簋」。"}]},{"id":"a339","section":"二世二年","anchor":"」二世曰：「吾聞之韓子曰：『堯舜采椽不刮，茅茨不翦，飯土塯，啜土形，","notes":[{"source":"集解","text":"如淳曰：「土形，飯器之屬，瓦器也。」"},{"source":"索隱","text":"飯器，以瓦爲之。"}]},{"id":"a340","section":"二世二年","anchor":"吾聞之韓子曰：『堯舜采椽不刮，茅茨不翦，飯土塯，啜土形，雖監門之養，","notes":[{"source":"正義","text":"以讓反。"}]},{"id":"a341","section":"二世二年","anchor":"曰：『堯舜采椽不刮，茅茨不翦，飯土塯，啜土形，雖監門之養，不觳於此。","notes":[{"source":"索隱","text":"謂監門之卒。養即卒也，有厮養卒。觳音學，謂盡也。又占學反。"},{"source":"正義","text":"又苦角反。《爾雅》云：「觳，盡也。」言堯舜采椽不刮，茅茨不翦，飯土塯，啜土形，雖監守門之人，供養亦不盡此之疏陋也。"}]},{"id":"a342","section":"二世二年","anchor":"，茅茨不翦，飯土塯，啜土形，雖監門之養，不觳於此。禹鑿龍門，通大夏，","notes":[{"source":"正義","text":"《括地志》云：「大夏，今并州晉陽及汾、絳等州是。昔高辛氏子實沈居之，西近河。」言禹鑿龍門，河水道，得大通，并州之地不壅溢也。"}]},{"id":"a343","section":"二世二年","anchor":"，飯土塯，啜土形，雖監門之養，不觳於此。禹鑿龍門，通大夏，決河亭水，","notes":[{"source":"正義","text":"亭，平也。又云「決亭壅之水。」"}]},{"id":"a344","section":"二世二年","anchor":"監門之養，不觳於此。禹鑿龍門，通大夏，決河亭水，放之海，身自持築臿，","notes":[{"source":"正義","text":"臿音初洽反，築牆杵也。臿，鍬也。《爾雅》云：「鍬謂之臿。」"}]},{"id":"a345","section":"二世二年","anchor":"通大夏，決河亭水，放之海，身自持築臿，脛毋毛，臣虜之勞不烈於此矣。』","notes":[{"source":"正義","text":"烈，美也。言臣虜之勞，猶不美於此矣。又烈，酷也。禹鑿龍門，通大夏，道決黃河洪水放之海，身持鍬杵，使膝脛無毛，賤臣奴虜之勤勞，不酷烈於此辛苦矣。"}]},{"id":"a346","section":"二世二年","anchor":"臿，脛毋毛，臣虜之勞不烈於此矣。』凡所爲貴有天下者，得肆意極欲，主重","notes":[{"source":"正義","text":"直拱反。"}]},{"id":"a347","section":"二世二年","anchor":"乘之屬，充吾號名。且先帝起諸侯，兼天下，天下已定，外攘四夷以安邊竟，","notes":[{"source":"正義","text":"音境。"}]},{"id":"a348","section":"二世二年","anchor":"盜並起，君不能禁，又欲罷先帝之所爲，是上毋以報先帝，次不爲朕盡忠力，","notes":[{"source":"正義","text":"爲，于僞反。"}]},{"id":"a349","section":"二世二年","anchor":"下去疾、斯、劫吏，案責他罪。去疾、劫曰：「將相不辱。」自殺。斯卒囚，","notes":[{"source":"正義","text":"卒，子律反。囚，在由反。謂禁錮也。"}]},{"id":"a350","section":"二世三年","anchor":"亦誅，無功亦誅。」項羽急擊秦軍，虜王離，邯等遂以兵降諸侯。八月己亥，","notes":[{"source":"集解","text":"徐廣曰：「一作『卯』。」"}]},{"id":"a351","section":"二世三年","anchor":"等軍數卻，上書請益助，燕、趙、齊、楚、韓、魏皆立爲王，自關以東，大氐","notes":[{"source":"正義","text":"丁禮反。氐猶略。"}]},{"id":"a352","section":"二世三年","anchor":"。二世夢白虎齧其左驂馬，殺之，心不樂，怪問占夢。卜曰：「涇水爲祟。」","notes":[{"source":"正義","text":"雖遂反。"}]},{"id":"a353","section":"二世三年","anchor":"驂馬，殺之，心不樂，怪問占夢。卜曰：「涇水爲祟。」二世乃齋於望夷宮，","notes":[{"source":"集解","text":"張晏曰：「望夷宮在長陵西北長平觀道東故亭處是也。臨涇水作之，以望北夷。」"},{"source":"正義","text":"《括地志》云：「秦望夷宮在雍州咸陽縣東南八里。張晏云臨涇水作之，望北夷。」"}]},{"id":"a354","section":"二世三年","anchor":"。吾欲易置上，更立公子嬰。子嬰仁儉，百姓皆載其言。」使郎中令爲內應，","notes":[{"source":"集解","text":"徐廣曰：「一云郎中令趙成。」"}]},{"id":"a355","section":"二世三年","anchor":"宮殿門，縛衞令僕射，曰：「賊入此，何不止？」衞令曰：「周廬設卒甚謹，","notes":[{"source":"集解","text":"西京賦曰：「徼道外周，千廬內傅。」薛綜曰：「士傅宮外，內爲廬舍，晝則巡行非常，夜則警備不虞。」"}]},{"id":"a356","section":"二世三年","anchor":"故得全。使臣蚤言，皆已誅，安得至今？」閻樂前即二世數曰：「足下驕恣，","notes":[{"source":"集解","text":"蔡邕曰：「羣臣士庶相與言，曰殿下、閣下、足下、侍者、執事，皆謙類。」"}]},{"id":"a357","section":"二世三年","anchor":"子嬰與其子二人謀曰：「丞相高殺二世望夷宮，恐羣臣誅之，乃詳以義立我。","notes":[{"source":"集解","text":"詳音羊。"}]},{"id":"a358","section":"二世三年","anchor":"族高家以徇咸陽。子嬰爲秦王四十六日，楚將沛公破秦軍入武關，遂至霸上，","notes":[{"source":"集解","text":"應劭曰：「霸水上地名，在長安東三十里。古名滋水，秦穆公更名霸水。」"}]},{"id":"a359","section":"二世三年","anchor":"沛公破秦軍入武關，遂至霸上，使人約降子嬰。子嬰即係頸以組，白馬素車，","notes":[{"source":"集解","text":"應劭曰：「組者，天子黻也。係頸者，言欲自殺。素車白馬，喪人之服也。」"}]},{"id":"a360","section":"二世三年","anchor":"霸上，使人約降子嬰。子嬰即係頸以組，白馬素車，奉天子璽符，降軹道旁。","notes":[{"source":"集解","text":"徐廣曰：「在霸陵。」駰案：蘇林曰「亭名，在長安東十三里」。"}]},{"id":"a361","section":"二世三年","anchor":"。沛公遂入咸陽，封宮室府庫，還軍霸上。居月餘，諸侯兵至，項籍爲從長，","notes":[{"source":"索隱","text":"謂合關東爲從長也。"}]},{"id":"a362","section":"二世三年","anchor":"而守之。然陳涉以戍卒散亂之眾數百，奮臂大呼，不用弓戟之兵，鉏櫌白梃，","notes":[{"source":"集解","text":"徐廣曰：「櫌，田器，音憂。」"},{"source":"索隱","text":"徐以櫌爲田器，非也。孟康以櫌爲鉏柄，蓋得其近也。"}]},{"id":"a363","section":"二世三年","anchor":"陳涉以戍卒散亂之眾數百，奮臂大呼，不用弓戟之兵，鉏櫌白梃，望屋而食，","notes":[{"source":"索隱","text":"言其兵蠶食天下，不裹糧而行。"}]},{"id":"a364","section":"二世三年","anchor":"散亂之眾數百，奮臂大呼，不用弓戟之兵，鉏櫌白梃，望屋而食，橫行天下。","notes":[{"source":"索隱","text":"謂輕前敵，不部伍旅進也。舞陽侯曰「橫行匈奴中」是也。"}]},{"id":"a365","section":"二世三年","anchor":"楚師深入，戰於鴻門，曾無藩籬之艱。於是山東大擾，諸侯並起，豪俊相立。","notes":[{"source":"集解","text":"駰案：鶡冠子曰「德萬人者謂之俊，德千人者謂之豪，德百人者謂之英」。"},{"source":"索隱","text":"謂武臣、田儋、魏豹之屬。"}]},{"id":"a366","section":"二世三年","anchor":"擾，諸侯並起，豪俊相立。秦使章邯將而東征，章邯因以三軍之眾要市於外，","notes":[{"source":"索隱","text":"此評失也。章邯之降，由趙高用事，不信任軍將，一則恐誅，二則楚兵既盛，王離見虜，遂以兵降耳。非三軍要市於外以求封明矣。要，平聲。"}]},{"id":"a367","section":"二世三年","anchor":"萬之徒逃北而遂壞。豈勇力智慧不足哉？形不利，勢不便也。秦小邑并大城，","notes":[{"source":"集解","text":"徐廣曰：「大，一作『小』。」"}]},{"id":"a368","section":"二世三年","anchor":"其下未附，名爲亡秦，其實利之也。彼見秦阻之難犯也，必退師。安土息民，","notes":[{"source":"索隱","text":"賈誼書「安」作「案」。"}]},{"id":"a369","section":"二世三年","anchor":"故秦之盛也，繁法嚴刑而天下振；及其衰也，百姓怨望而海內畔矣。故周五序","notes":[{"source":"索隱","text":"賈誼書「五」作「王」。"}]},{"id":"a370","section":"二世三年","anchor":"秦孝公據殽函之固，擁雍州之地，君臣固守而窺周室，有席卷天下，","notes":[{"source":"索隱","text":"按：春秋緯曰諸侯冰散席卷也。"}]},{"id":"a371","section":"二世三年","anchor":"，擁雍州之地，君臣固守而窺周室，有席卷天下，包舉宇內，囊括四海之意，","notes":[{"source":"集解","text":"張晏曰：「括，結囊也。言其能包含天下。」"},{"source":"索隱","text":"注同。"}]},{"id":"a372","section":"二世三年","anchor":"有席卷天下，包舉宇內，囊括四海之意，并吞八荒之心。當是時，商君佐之，","notes":[{"source":"索隱","text":"商君，衛公孫鞅，仕秦爲左庶長，遂爲秦制法，孝公致霸，封之於商，號商君。"}]},{"id":"a373","section":"二世三年","anchor":"心。當是時，商君佐之，內立法度，務耕織，修守戰之備，外連衡而鬬諸侯，","notes":[{"source":"索隱","text":"《戰國策》曰：「蘇秦亦爲秦連衡。」高誘曰：「合關東從通之秦，故曰連衡也。」"}]},{"id":"a374","section":"二世三年","anchor":"侯恐懼，會盟而謀弱秦，不愛珍器重寶肥美之地，以致天下之士，合從締交，","notes":[{"source":"集解","text":"《漢書音義》曰：「締，結也。」"}]},{"id":"a375","section":"二世三年","anchor":"，魏有信陵。此四君者，皆明知而忠信，寬厚而愛人，尊賢重士，約從離衡，","notes":[{"source":"索隱","text":"言孟嘗等四君皆爲其國共相約結爲從，以離散秦之橫。"}]},{"id":"a376","section":"二世三年","anchor":"，約從離衡，并韓、魏、燕、楚、齊、趙、宋、衞、中山之眾。於是六國之士","notes":[{"source":"索隱","text":"六國者，韓、魏、趙、燕、齊、楚是也。與秦爲七國，亦謂之七雄。又六國與宋、衞、中山爲九國。其三國蓋微，又前亡。"}]},{"id":"a377","section":"二世三年","anchor":"、宋、衞、中山之眾。於是六國之士有寧越、徐尚、蘇秦、杜赫之屬爲之謀，","notes":[{"source":"集解","text":"徐廣曰：「越，一作『經』。或自別有此人，不必甯越也。」"},{"source":"索隱","text":"寧越，趙人，賈誼作「甯越」。徐尚，未詳。蘇秦，東周洛陽人。呂氏春秋「杜赫以安天下說周昭文君」，高誘曰「杜赫，周人也」。"}]},{"id":"a378","section":"二世三年","anchor":"屬爲之謀，齊明、周最、陳軫、昭滑、樓緩、翟景、蘇厲、樂毅之徒通其意，","notes":[{"source":"索隱","text":"《戰國策》齊明，東周臣，後仕秦、楚及韓。周最，周之公子，亦仕秦。陳軫，夏人，亦仕秦。昭滑，楚人。樓緩，魏文侯弟，所謂樓子也。蘇厲，秦之弟，仕齊。樂毅本齊臣，入燕，燕昭王以客禮待之，以爲亞卿。翟景，未詳也。"}]},{"id":"a379","section":"二世三年","anchor":"徒通其意，吳起、孫臏、帶佗、兒良、王廖、田忌、廉頗、趙奢之朋制其兵。","notes":[{"source":"索隱","text":"吳起，衞人，事魏文侯爲將。孫臏，孫武之後也。呂氏春秋曰「王廖貴先，兒良貴後」，二人皆天下之豪士。田忌，齊將也。廉頗，趙將也。趙奢亦趙之將。"}]},{"id":"a380","section":"二世三年","anchor":"約解，爭割地而奉秦。秦有餘力而制其敝，追亡逐北，伏尸百萬，流血漂鹵。","notes":[{"source":"集解","text":"徐廣曰：「鹵，楯也。」"}]},{"id":"a381","section":"二世三年","anchor":"及至秦王，續六世之餘烈，","notes":[{"source":"集解","text":"張晏曰：「孝公、惠文王、武王、昭王、孝文王、莊襄王。」"}]},{"id":"a382","section":"二世三年","anchor":"續六世之餘烈，振長策而御宇內，吞二周而亡諸侯，履至尊而制六合，執棰拊","notes":[{"source":"集解","text":"徐廣曰：「拊，拍也，音府。一作『槁朴』。」"},{"source":"索隱","text":"賈本論作「槁朴」。"}]},{"id":"a383","section":"二世三年","anchor":"而亡諸侯，履至尊而制六合，執棰拊以鞭笞天下，威振四海。南取百越之地，","notes":[{"source":"集解","text":"韋昭曰：「越有百邑。」"}]},{"id":"a384","section":"二世三年","anchor":"馬，士不敢彎弓而報怨。於是廢先王之道，焚百家之言，以愚黔首。墮名城，","notes":[{"source":"集解","text":"應劭曰：「壞堅城，恐人復阻以害己也。」"}]},{"id":"a385","section":"二世三年","anchor":"下之兵聚之咸陽，銷鋒鑄鐻，以爲金人十二，以弱黔首之民。然後斬華爲城，","notes":[{"source":"集解","text":"徐廣曰：「斬，一作『踐』。」駰案：服虔曰「斷華山爲城」。"},{"source":"索隱","text":"斬，亦作「踐」，亦出賈本論。又崔浩云：「踐，登也。」"}]},{"id":"a386","section":"二世三年","anchor":"丈之城，臨不測之谿以爲固。良將勁弩守要害之處，信臣精卒陳利兵而誰何，","notes":[{"source":"集解","text":"如淳曰：「何猶問也。」"},{"source":"索隱","text":"崔浩云：「何或爲『呵』。」漢舊儀：「宿衞郎官分五夜誰呵，呵夜行者誰也。」何呵字同。"}]},{"id":"a387","section":"二世三年","anchor":"信臣精卒陳利兵而誰何，天下以定。秦王之心，自以爲關中之固，金城千里，","notes":[{"source":"索隱","text":"金城，言其實且堅也。韓子曰「雖有金城湯池」，《漢書》張良亦曰「關中所謂金城千里，天府之國。」"}]},{"id":"a388","section":"二世三年","anchor":"秦王既沒，餘威振於殊俗。陳涉，罋牖繩樞之子，","notes":[{"source":"集解","text":"服虔曰：「以繩係戶樞也。」孟康曰：「瓦罋爲窻也。」"}]},{"id":"a389","section":"二世三年","anchor":"秦王既沒，餘威振於殊俗。陳涉，罋牖繩樞之子，甿隸之人，","notes":[{"source":"集解","text":"如淳曰：「甿，古『氓』字。氓，民也。」"}]},{"id":"a390","section":"二世三年","anchor":"，非有仲尼、墨翟之賢，陶朱、猗頓之富，躡足行伍之閒，而倔起什伯之中，","notes":[{"source":"集解","text":"《漢書音義》曰：「首出十長百長之中。」如淳曰：「時皆辟屈在十百之中。」"}]},{"id":"a391","section":"二世三年","anchor":"且夫天下非小弱也，雍州之地，殽函之固自若也。","notes":[{"source":"集解","text":"韋昭曰：「殽謂二殽。函，函谷關也。」"}]},{"id":"a392","section":"二世三年","anchor":"陳涉之位，非尊於齊、楚、燕、趙、韓、魏、宋、衞、中山之君；鉏櫌棘矜，","notes":[{"source":"集解","text":"服虔曰：「以鉏柄及棘作矛槿也。」如淳曰：「櫌椎，塊椎也。」"}]},{"id":"a393","section":"二世三年","anchor":"、楚、燕、趙、韓、魏、宋、衞、中山之君；鉏櫌棘矜，非錟於句戟長鎩也；","notes":[{"source":"集解","text":"徐廣曰：「錟，一作『銛』。」駰案：如淳曰「長刃矛也」。又曰「鉤戟似矛，刃下有鐵，橫方上鉤曲也」。鎩音所拜反。"}]},{"id":"a394","section":"二世三年","anchor":"及鄉時之士也。然而成敗異變，功業相反也。試使山東之國與陳涉度長絜大，","notes":[{"source":"集解","text":"《漢書音義》曰：「『絜東』之『絜』。」"}]},{"id":"a395","section":"二世三年","anchor":"秦并海內，兼諸侯，南面稱帝，","notes":[{"source":"集解","text":"徐廣曰：「一本有此篇，無前者『秦孝公』已下，而又以『秦并兼諸侯山東三十餘郡』繼此末也。」"},{"source":"索隱","text":"按：賈誼過秦論以「孝公」已下爲上篇，「秦兼并諸侯山東三十餘郡」爲下篇。鄒誕生云「太史公刪賈誼過秦篇著此論，富其義而省其辭。褚先生增續既已混殽，而世俗小智不唯刪省之旨，合寫本論於此，故不同也。今頗亦不可分別」。"}]},{"id":"a396","section":"二世三年","anchor":"今秦二世立，天下莫不引領而觀其政。夫寒者利裋褐","notes":[{"source":"集解","text":"徐廣曰：「一作『短』，小襦也，音豎。」"},{"source":"索隱","text":"趙岐曰：「褐以毛毳織之，若馬衣。或以褐編衣也。」裋，一音豎。謂褐布豎裁，爲勞役之衣，短而且狹，故謂之短褐，亦曰豎褐。"}]},{"id":"a397","section":"二世三年","anchor":"無以飾其智，而暴亂之姦止矣。二世不行此術，而重之以無道，壞宗廟與民，","notes":[{"source":"集解","text":"徐廣曰：「一無此上五字。」"}]},{"id":"a398","section":"二世三年","anchor":"襄公立，享國十二年。初爲西畤。葬西垂。","notes":[{"source":"索隱","text":"此已下重序列秦之先君立年及葬處，皆當據秦紀爲說，與正史小有不同，今取異說重列於後。襄公，秦仲孫，莊公子，救周，周始命爲諸侯。初爲西畤，祠白帝。立十三年，葬西土。"}]},{"id":"a399","section":"二世三年","anchor":"文公立，居西垂宮。五十年死，葬西垂。","notes":[{"source":"索隱","text":"作鄜畤，又作陳寶祠。"}]},{"id":"a400","section":"二世三年","anchor":"憲公享國十二年，居西新邑。死，葬衙。","notes":[{"source":"集解","text":"《地理志》云馮翊有衙縣。"},{"source":"索隱","text":"憲公滅蕩社，居新邑，葬衙。本紀憲公徙居平陽，葬西山。"}]},{"id":"a401","section":"二世三年","anchor":"出子享國六年，居西陵。","notes":[{"source":"索隱","text":"一云居西陂，葬衙。本紀不云。"}]},{"id":"a402","section":"二世三年","anchor":"武公享國二十年。居平陽封宮。","notes":[{"source":"集解","text":"徐廣曰：「一云居平封宮。」"}]},{"id":"a403","section":"二世三年","anchor":"武公享國二十年。居平陽封宮。葬宣陽聚東南。","notes":[{"source":"索隱","text":"紀云葬平陽，初以人從死。"}]},{"id":"a404","section":"二世三年","anchor":"德公享國二年。居雍大鄭宮。生宣公、成公、繆公。葬陽。初伏，以御蠱。","notes":[{"source":"索隱","text":"二年初伏。本紀此已下居葬絕不言也。"}]},{"id":"a405","section":"二世三年","anchor":"宣公享國十二年。居陽宮。葬陽。","notes":[{"source":"索隱","text":"四年，作密畤。"}]},{"id":"a406","section":"二世三年","anchor":"成公享國四年，居雍之","notes":[{"source":"集解","text":"徐廣曰：「之，一作『走』。」"}]},{"id":"a407","section":"二世三年","anchor":"繆公享國三十九年。天子致霸。葬雍。繆公學著人。","notes":[{"source":"索隱","text":"著音宁，又音貯，著即宁也。門屏之閒曰宁，謂學於宁門之人。故《詩》云「俟我於著乎而」是也。"}]},{"id":"a408","section":"二世三年","anchor":"桓公享國二十七年。居雍太寢。葬義里丘北。生景公。","notes":[{"source":"索隱","text":"一作「僖公」。《系本》云名后伯車。"}]},{"id":"a409","section":"二世三年","anchor":"景公享國四十年。居雍高寢，葬丘里南。","notes":[{"source":"正義","text":"丘，一作「二」也。"}]},{"id":"a410","section":"二世三年","anchor":"景公享國四十年。居雍高寢，葬丘里南。生畢公。","notes":[{"source":"集解","text":"徐廣曰：「春秋作『哀公』。」"}]},{"id":"a411","section":"二世三年","anchor":"畢公享國三十六年。","notes":[{"source":"正義","text":"一作「三十七年」。"}]},{"id":"a412","section":"二世三年","anchor":"夷公不享國。死，葬左宮。生惠公。","notes":[{"source":"正義","text":"十年，葬車里。元年，孔子行魯相事。"}]},{"id":"a413","section":"二世三年","anchor":"悼公享國十五年。","notes":[{"source":"正義","text":"（雍）本紀作「十四年」。"}]},{"id":"a414","section":"二世三年","anchor":"悼公享國十五年。葬僖公西。城雍。生剌","notes":[{"source":"正義","text":"一作「利」。"}]},{"id":"a415","section":"二世三年","anchor":"悼公享國十五年。葬僖公西。城雍。生剌龔公","notes":[{"source":"索隱","text":"一作「厲共公」。"}]},{"id":"a416","section":"二世三年","anchor":"剌龔公享國三十四年。葬入里。","notes":[{"source":"集解","text":"徐廣曰：「一作『人』。」"}]},{"id":"a417","section":"二世三年","anchor":"剌龔公享國三十四年。葬入里。生躁公、","notes":[{"source":"索隱","text":"又作「趮公」。"},{"source":"正義","text":"十四年，居受寢，葬悼公南也。"}]},{"id":"a418","section":"二世三年","anchor":"剌龔公享國三十四年。葬入里。生躁公、懷公。","notes":[{"source":"正義","text":"四年，葬櫟圉氏。"}]},{"id":"a419","section":"二世三年","anchor":"躁公享國十四年。居受寢。葬悼公南。其元年，彗星見。","notes":[{"source":"集解","text":"徐廣曰：「年表云『星晝見』。」"}]},{"id":"a420","section":"二世三年","anchor":"肅靈公，昭子子也。","notes":[{"source":"集解","text":"徐廣曰：「懷公生昭子，昭子生靈公。」"},{"source":"索隱","text":"紀年及《系本》無「肅」字。立十年，表同，紀十二年。"}]},{"id":"a421","section":"二世三年","anchor":"簡公從晉來。享國十五年。葬僖公西。","notes":[{"source":"索隱","text":"按：本紀簡公名悼子，即剌龔公之子，懷公弟也。且紀及《系本》皆以爲然，今此文云「靈公」，謬也。立十六年，葬僖公西。"}]},{"id":"a422","section":"二世三年","anchor":"惠公享國十三年。葬陵圉。","notes":[{"source":"索隱","text":"王劭按紀年云「簡公後次敬公，敬公立十三年，乃至惠公」，辭即難憑，時參異說。"}]},{"id":"a423","section":"二世三年","anchor":"出公享國二年。","notes":[{"source":"索隱","text":"《系本》謂「少主」。"}]},{"id":"a424","section":"二世三年","anchor":"獻公享國二十三年。","notes":[{"source":"集解","text":"徐廣曰：「靈公子。」"},{"source":"索隱","text":"《系本》稱「元獻公」。立二十二年，表同，紀二十四年。"}]},{"id":"a425","section":"二世三年","anchor":"孝公享國二十四年。","notes":[{"source":"索隱","text":"本紀十二年。"}]},{"id":"a426","section":"二世三年","anchor":"孝公享國二十四年。葬弟圉。生惠文王。其十三年，始都咸陽。","notes":[{"source":"正義","text":"本紀云「十二年作咸陽，築冀闕」，是十三年始都之。"}]},{"id":"a427","section":"二世三年","anchor":"惠文王享國二十七年。","notes":[{"source":"索隱","text":"十九而立。"}]},{"id":"a428","section":"二世三年","anchor":"惠文王享國二十七年。葬公陵。","notes":[{"source":"正義","text":"《括地志》云：「秦惠文王陵在雍州咸陽縣西北一十四里。」"}]},{"id":"a429","section":"二世三年","anchor":"悼武王享國四年，葬永陵。","notes":[{"source":"集解","text":"徐廣曰：「皇甫謐曰葬畢，今按陵西畢陌。」"},{"source":"索隱","text":"《系本》作「武烈王」。十九而立，立三年。本紀四年。"},{"source":"正義","text":"《括地志》云：「秦悼武王陵在雍州咸陽縣西十里，俗名周武王陵，非也。」"}]},{"id":"a430","section":"二世三年","anchor":"昭襄王享國五十六年。葬茝陽。","notes":[{"source":"索隱","text":"十九年而立，葬芷陵也。"},{"source":"正義","text":"《括地志》云：「秦莊襄王陵在雍州新豐縣西南三十五里，俗亦謂爲子楚。始皇陵在北，故亦謂爲見子陵。」"}]},{"id":"a431","section":"二世三年","anchor":"始皇享國三十七年。葬酈邑。","notes":[{"source":"正義","text":"酈，力知反。"}]},{"id":"a432","section":"二世三年","anchor":"二世皇帝享國三年。葬宜春。","notes":[{"source":"正義","text":"《括地志》云：「秦故胡亥陵在雍州萬年縣南三十四里。」上文「葬以黔首」也。"}]},{"id":"a433","section":"二世三年","anchor":"二世皇帝享國三年。葬宜春。趙高爲丞相安武侯。二世生十二年而立。","notes":[{"source":"集解","text":"徐廣曰：「本紀云二十一。」"}]},{"id":"a434","section":"二世三年","anchor":"右秦襄公至二世，六百一十歲。","notes":[{"source":"正義","text":"《秦本紀》自襄公至二世，五百七十六年矣。年表自襄公至二世，五百六十一年。三說並不同，未知孰是。"}]},{"id":"a435","section":"二世三年","anchor":"孝明皇帝十七年","notes":[{"source":"正義","text":"班固典引云後漢明帝永平十七年，詔問班固：「太史遷贊語中寧有非邪？」班固上表陳秦過失及賈誼言答之。"}]},{"id":"a436","section":"二世三年","anchor":"孝明皇帝十七年十月十五日乙丑，曰：","notes":[{"source":"索隱","text":"此已下是漢孝明帝訪班固評賈馬贊中論秦二世亡天下之得失，後人因取其說附之此末。"}]},{"id":"a437","section":"二世三年","anchor":"周曆已移，","notes":[{"source":"正義","text":"周初卜世三十，卜年七百，以五序得其道，故王至三十七，歲至八百六十七。曆數既過，秦并天下，是周曆已移也。"}]},{"id":"a438","section":"二世三年","anchor":"周曆已移，仁不代母。秦直其位，","notes":[{"source":"索隱","text":"周曆已移，周亡也。仁不代母，謂周得木德，木生火，周爲漢母也。言曆運之道，仁恩之情，子不代母而王，謂火不代木，言漢不合即代周也。秦值其閏位，得在木火之閒也。此論者之辭也。"},{"source":"正義","text":"始皇以爲周火德，秦代周從所不勝，爲水德之始也。按：周木德也，秦水德也。五行之運，水生木，木生火，火生土，土生金，金生水。所生者爲母，出者爲子。帝王之次，子代母。秦稱水是母代子，故言若有德之君相代，不母承其子。直音值。言秦并天下稱帝，是秦德值帝王之位。"}]},{"id":"a439","section":"二世三年","anchor":"周曆已移，仁不代母。秦直其位，呂政殘虐。然以諸侯十三，","notes":[{"source":"集解","text":"始皇初爲秦王，年十三也。"},{"source":"索隱","text":"呂政者，始皇名政，是呂不韋幸姬有娠，獻莊襄王而生始皇，故云呂政。"}]},{"id":"a440","section":"二世三年","anchor":"天下，極情縱欲，養育宗親。三十七年，兵無所不加，制作政令，施於後王。","notes":[{"source":"正義","text":"謂置郡縣，壞井田，開阡陌，不立侯王，始爲伏臘；又置丞相、太尉、御史大夫、奉常、郎中令、僕射、廷尉、典客、宗正、少府、中尉、將作、詹事、水衡都尉、監、守、縣令、丞等，皆施於後王，至于隋、唐矣。"}]},{"id":"a441","section":"二世三年","anchor":"。三十七年，兵無所不加，制作政令，施於後王。蓋得聖人之威，河神授圖，","notes":[{"source":"正義","text":"蓋者，疑辭也。言始皇之威，能吞并天下稱帝，疑得聖人之威靈，河神之圖錄。"}]},{"id":"a442","section":"二世三年","anchor":"令，施於後王。蓋得聖人之威，河神授圖，據狼、狐，蹈參、伐，佐政驅除，","notes":[{"source":"正義","text":"狼音郎。狼，狐，主弓矢星。《天官書》云參伐主斬艾事。言秦據蹈狼、狐、參、伐之氣，驅滅天下。"}]},{"id":"a443","section":"二世三年","anchor":"施於後王。蓋得聖人之威，河神授圖，據狼、狐，蹈參、伐，佐政驅除，距之","notes":[{"source":"正義","text":"上音巨。之，至也。"}]},{"id":"a444","section":"二世三年","anchor":"欲，大臣至欲罷先君所爲」。誅斯、去疾，任用趙高。痛哉言乎！人頭畜鳴。","notes":[{"source":"正義","text":"畜，許又反。言胡亥人身有頭面，口能言語，不辨好惡，若六畜之鳴。"}]},{"id":"a445","section":"二世三年","anchor":"罷先君所爲」。誅斯、去疾，任用趙高。痛哉言乎！人頭畜鳴。不威不伐惡，","notes":[{"source":"正義","text":"此五字爲一句也。"}]},{"id":"a446","section":"二世三年","anchor":"。誅斯、去疾，任用趙高。痛哉言乎！人頭畜鳴。不威不伐惡，不篤不虛亡，","notes":[{"source":"正義","text":"言胡亥藉帝王之威器，殘酷暴虐滋己惡，惡既深篤，以至滅亡，豈其虛哉。"}]},{"id":"a447","section":"二世三年","anchor":"子嬰度次得嗣，冠玉冠，","notes":[{"source":"正義","text":"上「冠」音綰。"}]},{"id":"a448","section":"二世三年","anchor":"子嬰度次得嗣，冠玉冠，佩華紱，","notes":[{"source":"正義","text":"音拂。"}]},{"id":"a449","section":"二世三年","anchor":"子嬰度次得嗣，冠玉冠，佩華紱，車黃屋，","notes":[{"source":"集解","text":"蔡邕曰：「黃屋者，蓋以黃爲裏。」"}]},{"id":"a450","section":"二世三年","anchor":"子嬰度次得嗣，冠玉冠，佩華紱，車黃屋，從","notes":[{"source":"正義","text":"才用反。"}]},{"id":"a451","section":"二世三年","anchor":"失守，偷安日日，獨能長念卻慮，父子作權，近取於戶牖之閒，竟誅猾臣，爲","notes":[{"source":"正義","text":"于僞反。"}]},{"id":"a452","section":"二世三年","anchor":"，真人翔霸上，素車嬰組，奉其符璽，以歸帝者。鄭伯茅旌鸞刀，嚴王退舍。","notes":[{"source":"集解","text":"《公羊傳》曰：「楚莊王伐鄭，鄭伯肉袒，左執茅旌，右執鸞刀，以逆莊王，莊王退舍七里。」何休曰：「茅旌，鸞刀，祭祀宗廟所用也。執宗廟器者，示以宗廟血食自歸。」"},{"source":"正義","text":"旌音精。嚴音莊。"}]},{"id":"a453","section":"二世三年","anchor":"符璽，以歸帝者。鄭伯茅旌鸞刀，嚴王退舍。河決不可復壅，魚爛不可復全。","notes":[{"source":"索隱","text":"宋均曰：「言如魚之爛，從內而出。」"}]},{"id":"a454","section":"二世三年","anchor":"東雖亂，秦之地可全而有，宗廟之祀未當絕也。」秦之積衰，天下土崩瓦解，","notes":[{"source":"正義","text":"言秦國敗壞，若屋宇崩穨，眾瓦解散也。"}]},{"id":"a455","section":"二世三年","anchor":"秦之積衰，天下土崩瓦解，雖有周旦之材，無所復陳其巧，而以責一日之孤，","notes":[{"source":"正義","text":"日音馹。一日之孤謂子嬰。"}]},{"id":"a456","section":"二世三年","anchor":"而以責一日之孤，誤哉！俗傳秦始皇起罪惡，胡亥極，得其理矣。復責小子，","notes":[{"source":"正義","text":"亦謂子嬰。"}]},{"id":"a457","section":"二世三年","anchor":"其理矣。復責小子，云秦地可全，所謂不通時變者也。紀季以酅，春秋不名。","notes":[{"source":"集解","text":"春秋曰：「紀季以酅入于齊。」《公羊傳》曰：「何以不名？賢之也。謂設五廟以存姑姊妹也。」"},{"source":"正義","text":"酅音戶圭反。《括地志》云：「安平城在青州臨淄縣東十九里，古紀之酅邑。《帝王紀》云周之紀國，姜姓也。紀侯譖齊哀公於周懿王，王烹之。外傳曰紀侯入爲周士。竹《書》云齊襄公滅紀、郱、鄑、郚。」又《括地志》云：「郱城在青州臨朐縣東三十里。鄑城在北海縣東北七十里。郚城在密州安丘縣界。」郱音駢。鄑音訾。按：秦始皇起罪惡，胡亥極，得其理。國既崩絕，箕子、比干尚不能存殷，庸主子嬰焉能救秦之敗？以賈誼、史遷不通時變，不如紀季之深識也。季，紀侯少弟，不書名，故曰紀季。"}]},{"id":"a458","section":"二世三年","anchor":"。吾讀秦紀，至於子嬰車裂趙高，未嘗不健其決，憐其志。嬰死生之義備矣。","notes":[{"source":"集解","text":"徐廣曰：「班固典引曰『永平十七年，詔問臣固，太史遷贊語中寧有非邪？臣對，賈誼言子嬰得中佐，秦未絕也。此言非是，臣素知之耳』。」"}]}]'),s=[],r={id:"006",volume:6,sanjiazhuSourceUrl:t,originalSourceUrl:e,annotations:o,criticalNotes:s};export{o as annotations,s as criticalNotes,r as default,c as id,e as originalSourceUrl,t as sanjiazhuSourceUrl,n as volume};
